DG.put("vaar-durgaa-kee/1",{"n":1,"title":null,"title_roman":null,"page":240,"blocks":[{"type":"heading","kind":"announcement","name":"ਅਥ ਵਾਰ ਦੁਰਗਾ ਕੀ ਲਿਖ੍ਯਤੇ","gurmukhi":"ਅਥ ਵਾਰ ਦੁਰਗਾ ਕੀ ਲਿਖ੍ਯਤੇ।","roman":"Ath vaar durgaa kee likhyate |","meaning_en":"Now begins the Var of Durga.","page":240,"meaning_status":"draft"},{"type":"invocation","gurmukhi":"ਪਾਤਿਸਾਹੀ ੧੦","roman":"Paatisaahee 10","meaning_en":"The Tenth King (Guru Gobind Singh).","page":240,"meaning_status":"draft","note":"ਪਾਤਿਸਾਹੀ ੧੦: 'the tenth sovereign', i.e. the Tenth Guru."},{"type":"heading","kind":"chhand","name":"ਪਉੜੀ","gurmukhi":"ਪਉੜੀ","roman":"Pauree","meaning_en":"Pauri.","page":240,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":240,"lines":[{"gurmukhi":"ਪ੍ਰਥਮਿ ਭਗਉਤੀ ਸਿਮਰਕੈ ਗੁਰੂ ਨਾਨਕ ਲਈ ਧਿਆਇ।","roman":"Prathmi bhagautee simarkai guroo naanak laee dhiaai |","meaning_en":"First remembering Bhagauti, then meditate on Guru Nanak;","page":240,"meaning_status":"draft","note":"ਭਗਉਤੀ: the Primal Power / the Sword, as a name of God; left as 'Bhagauti'."},{"gurmukhi":"ਅੰਗਦ ਗਰੂ ਤੇ ਅਮਰਦਾਸ ਰਾਮਦਾਸੈ ਹੋਈ ਸਹਾਇ।","roman":"Angad garoo te amardaas raamdaasai hoee sahaai |","meaning_en":"then Guru Angad, Amar Das and Ram Das; may they be my help.","page":240,"flags":[{"code":"ੁ+ੂ","reason":"overlapping ੁ and ੂ drawn as one ੂ"}],"meaning_status":"draft","note":"ਗਰੂ: printed so; read as ਗੁਰੂ. ਹੋਈ ਸਹਾਇ: 'be (my) help'; may also be read as 'who become helpers'."},{"gurmukhi":"ਅਰਜੁਨ ਹਰਿਗੋਬਿੰਦ ਨੋ ਸਿਮਰੋ ਸ੍ਰੀ ਹਰਿ ਰਾਇ।","roman":"Arjun harigobind no simro sree hari raai |","meaning_en":"Remember Arjan, Hargobind and the revered Har Rai.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਕ੍ਰਿਸਨਿ ਧਿਆਇਐ ਜਿਸੁ ਡਿਠੇ ਸਭੁ ਦੁਖੁ ਜਾਇ।","roman":"Sree hari krisni dhiaaiai jisu dithe sabhu dukhu jaai |","meaning_en":"Meditate on the revered Har Krishan, at whose sight all suffering departs.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਤੇਗ ਬਹਾਦੁਰ ਸਿਮਰੀਐ ਘਰਿ ਨੌਨਿਧ ਆਵੈ ਧਾਇ।","roman":"Teg bahaadur simreeai ghari naunidh aavai dhaai |","meaning_en":"Remember Tegh Bahadur, and the nine treasures come running to your home.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਥਾਈ ਹੋਇ ਸਹਾਇ। ੧।","roman":"Sabh thaaee hoi sahaai | 1 |","meaning_en":"May they be my help in every place. (1)","page":240,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":240,"lines":[{"gurmukhi":"ਖੰਡਾ ਪ੍ਰਥਮਿ ਮਨਾਇਕੈ ਜਿਨ ਸਭ ਸੈਸਾਰ ਉਪਾਇਆ।","roman":"Khandaa prathmi manaaikai jin sabh saisaar upaaiaa |","meaning_en":"First invoking the Khanda (the double-edged sword, the Lord) who created the whole world,","page":240,"meaning_status":"draft","note":"ਖੰਡਾ: the double-edged sword, here standing for the Creator."},{"gurmukhi":"ਬ੍ਰਹਮਾ ਬਿਸਨੁ ਮਹੇਸ ਸਾਜਿ ਕੁਦਰਤਿ ਦਾ ਖੇਲੁ ਬਣਾਇਆ।","roman":"Brahmaa bisnu mahes saaji kudarti daa khelu banaaiaa |","meaning_en":"who fashioned Brahma, Vishnu and Shiva and set up the play of creation;","page":240,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧੁ ਪਰਬਤ ਮੇਦਨੀ ਬਿਨੁ ਥੰਮਾ ਗਗਨ ਰਹਾਇਆ।","roman":"Sindhu parbat mednee binu thanmaa gagan rahaaiaa |","meaning_en":"who made the oceans, mountains and earth, and kept the sky standing without pillars;","page":240,"meaning_status":"draft"},{"gurmukhi":"ਸਿਰਜੇ ਦਾਨੋ ਦੇਵਤੇ ਤਿਨ ਅੰਦਰਿ ਬਾਦੁ ਰਚਾਇਆ।","roman":"Sirje daano devte tin andri baadu rachaaiaa |","meaning_en":"who created the demons and the gods and set strife among them.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਤੈ ਹੀ ਦੁਰਗਾ ਸਾਜਿਕੈ ਦੈਤਾ ਦਾ ਨਾਸ ਕਰਾਇਆ।","roman":"Tai hee durgaa saajikai daitaa daa naas karaaiaa |","meaning_en":"You alone created Durga and had the demons destroyed by her.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਤੈਥੋ ਹੀ ਬਲੁ ਰਾਮ ਲੈ ਨਾਲ ਬਾਣਾ ਰਾਵਣੁ ਘਾਇਆ।","roman":"Taitho hee balu raam lai naal baanaa raavnu ghaaiaa |","meaning_en":"From You alone Ram took strength and killed Ravan with his arrows.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਤੈਥੋ ਹੀ ਬਲੁ ਕ੍ਰਿਸਨ ਲੈ ਕੰਸ ਕੇਸੀ ਪਕੜਿ ਗਿਰਾਇਆ।","roman":"Taitho hee balu krisan lai kans kesee pakri giraaiaa |","meaning_en":"From You alone Krishna took strength, seized Kans by the hair and threw him down.","page":240,"meaning_status":"draft","note":"ਕੰਸ ਕੇਸੀ: read as 'Kans by the hair (kesi)'; may also be read as 'Kans and (the demon) Keshi'; uncertain."},{"gurmukhi":"ਬਡੇ ਬਡੇ ਮੁਨਿ ਦੇਵਤੇ ਕਈ ਜੁਗ ਤਿਨੀ ਤਨ ਤਾਇਆ।","roman":"Bade bade muni devte kaee jug tinee tan taaiaa |","meaning_en":"Great sages and gods practised austerities, burning their bodies for many ages;","page":240,"meaning_status":"draft"},{"gurmukhi":"ਕਿਨੈ ਤੇਰਾ ਅੰਤ ਨ ਪਾਇਆ। ੨।","roman":"Kinai teraa ant na paaiaa | 2 |","meaning_en":"none has found Your limit. (2)","page":240,"meaning_status":"draft"}]},{"type":"verse","number":[3],"number_text":"੩।","page":240,"lines":[{"gurmukhi":"ਸਾਧੂ ਸਤਿਜੁਗ ਬੀਤਿਆ ਅਧਸੀਲੀ ਤ੍ਰੇਤਾ ਆਇਆ।","roman":"Saadhoo satijug beetiaa adhseelee tretaa aaiaa |","meaning_en":"The virtuous Satyug passed, and the half-virtuous Treta came.","page":240,"meaning_status":"draft","note":"ਅਧਸੀਲੀ: 'half-virtuous'."},{"gurmukhi":"ਨਚੀ ਕਲਿ ਸਰੋਸਰੀ ਕਲਿ ਨਾਰਦ ਡਉਰੂ ਵਾਇਆ।","roman":"Nachee kali sarosree kali naarad dauroo vaaiaa |","meaning_en":"Strife danced on every head, and Kal and Narad sounded the dumroo.","page":240,"meaning_status":"draft","note":"ਕਲਿ ਸਰੋਸਰੀ: read as 'strife (kal) over every head'; uncertain. ਕਲਿ ਨਾਰਦ: 'Kal (strife/the age) and Narad'; uncertain."},{"gurmukhi":"ਅਭਿਮਾਨ ਉਤਾਰਨ ਦਿਉਤਿਆ ਮਹਿਖਾਸੁਰ ਸੁੰਭ ਉਪਾਇਆ।","roman":"Abhimaan utaaran diutiaa mahikhaasur sunbh upaaiaa |","meaning_en":"To humble the pride of the gods, Mahishasur and Sumbh were brought into being.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤ ਲਏ ਤਿਨਿ ਦੇਵਤੇ ਤਿਹੁ ਲੋਕੀ ਰਾਜੁ ਕਮਾਇਆ।","roman":"Jeet lae tini devte tihu lokee raaju kamaaiaa |","meaning_en":"They conquered the gods and ruled over the three worlds.","page":240,"meaning_status":"draft"},{"gurmukhi":"ਵਡਾ ਬੀਰ ਅਖਾਇ ਕੈ ਸਿਰ ਉਪਰਿ ਛਤ੍ਰ ਫਿਰਾਇਆ।","roman":"Vadaa beer akhaai kai sir upri chhatr phiraaiaa |","meaning_en":"Calling himself a great hero, he had the canopy waved over his head.","page":241,"meaning_status":"draft","note":"ਛਤ੍ਰ ਫਿਰਾਇਆ: had the royal canopy held over him, i.e. took sovereignty."},{"gurmukhi":"ਦਿਤਾ ਇੰਦ੍ਰ ਨਿਕਾਲ ਕੇ ਤਿਨਿ ਗਿਰ ਕੈਲਾਸੁ ਤਕਾਇਆ।","roman":"Ditaa indr nikaal ke tini gir kailaasu takaaiaa |","meaning_en":"He drove Indra out, and Indra looked towards Mount Kailash.","page":241,"meaning_status":"draft","note":"ਤਕਾਇਆ: 'looked to / set out for' Kailash."},{"gurmukhi":"ਡਰ ਕੈ ਹਥੋਂ ਦਾਨਵੀ ਦਿਲ ਅੰਦਰਿ ਤ੍ਰਾਸ ਵਧਾਇਆ।","roman":"Dar kai hathon daanvee dil andri traas vadhaaiaa |","meaning_en":"Frightened at the hands of the demons, great dread grew in his heart.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਪਾਸ ਦੁਰਗਾ ਦੇ ਇੰਦ੍ਰੁ ਆਇਆ। ੩।","roman":"Paas durgaa de indru aaiaa | 3 |","meaning_en":"Indra came to Durga. (3)","page":241,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":241,"lines":[{"gurmukhi":"ਇਕ ਦਿਹਾੜੈ ਆਈ ਨ੍ਹਾਵਣ ਦੁਰਗ ਸਾਹ। ਇੰਦ੍ਰ ਬ੍ਰਿਥਾ ਸੁਣਾਈ ਆਪਣੇ ਹਾਲ ਦੀ।","roman":"Ik dihaarai aaee nhaavan durag saah | indr brithaa sunaaee aapne haal dee |","meaning_en":"One day Durga, the sovereign, came to bathe. Indra told her the tale of his plight:","page":241,"meaning_status":"draft","note":"ਦੁਰਗ ਸਾਹ: 'Durga the sovereign (shah)'."},{"gurmukhi":"ਛੀਨਿ ਲਈ ਠਕੁਰਾਈ ਸਾਤੇ ਦਾਨਵੀ। ਲੋਕੀ ਤਿਹੀ ਫਿਰਾਈ ਦੋਹੀ ਆਪਣੀ।","roman":"Chheeni laee thakuraaee saate daanvee | lokee tihee phiraaee dohee aapnee |","meaning_en":"\"The demons have snatched away our sovereignty; they have proclaimed their rule in all three worlds.","page":241,"meaning_status":"draft","note":"ਸਾਤੇ: read as 'from us' (sathon); uncertain. ਦੋਹੀ ਫਿਰਾਈ: proclaimed their authority."},{"gurmukhi":"ਬੈਠੇ ਵਾਇ ਵਧਾਈ ਤੇ ਅਮਰਾਵਤੀ। ਦਿਤੇ ਦੇਵ ਭਜਾਈ ਸਭਨਾ ਰਾਕਸਾ।","roman":"Baithe vaai vadhaaee te amraavtee | dite dev bhajaaee sabhnaa raaksaa |","meaning_en":"They sit in Amravati with drums of rejoicing playing; they have put all the gods to flight.","page":241,"meaning_status":"draft","note":"ਵਾਇ ਵਧਾਈ: 'sounding (drums of) congratulation'; uncertain."},{"gurmukhi":"ਕਿਨੈ ਨ ਜਿਤਿਆ ਜਾਈ ਮਹਿਖੈ ਦੈਤ ਨੂੰ। ਤੇਰੀ ਸਾਮ ਤਕਾਈ ਦੇਵੀ ਦੁਰਗਸਾਹ। ੪।","roman":"Kinai na jitiaa jaaee mahikhai dait noon | teree saam takaaee devee duragsaah | 4 |","meaning_en":"No one can conquer the demon Mahishasur; O goddess Durga, I have come to your shelter.\" (4)","page":241,"meaning_status":"draft","note":"ਮਹਿਖੈ ਦੈਤ: 'the demon Mahikha', i.e. Mahishasur. ਸਾਮ: shelter, refuge."}]},{"type":"verse","number":[5],"number_text":"੫।","page":241,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਬੈਣ ਸੁਣੰਦੀ ਹਸੀ ਹੜ ਹੜਾਇ। ਓਹੀ ਸੀਹੁ ਬੁਲਾਇਆ ਰਾਕਸ ਭਖਣਾ।","roman":"Durgaa bain sunandee hasee har haraai | ohee seehu bulaaiaa raakas bhakhnaa |","meaning_en":"Hearing these words, Durga laughed aloud. She called that lion, the devourer of demons.","page":241,"meaning_status":"draft","note":"ਹੜ ਹੜਾਇ: loud laughter, a sound-word."},{"gurmukhi":"ਚਿੰਤਾ ਕਰਹੁ ਨ ਕਾਈ ਦੇਵਾ ਨੂੰ ਆਖਿਆ। ਰੋਹ ਹੋਈ ਮਹਾਮਾਈ ਰਾਕਸਿ ਮਾਰਣੇ। ੫।","roman":"Chintaa karhu na kaaee devaa noon aakhiaa | roh hoee mahaamaaee raaksi maarne | 5 |","meaning_en":"She said to the gods, \"Have no worry at all.\" The Great Mother grew wrathful to kill the demons. (5)","page":241,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":241,"meaning_status":"draft"},{"type":"verse","number":[6],"number_text":"੬।","page":241,"lines":[{"gurmukhi":"ਰਾਕਸ ਆਏ ਰੋਹਲੇ ਖੇਤਿ ਭਿੜਨ ਕੇ ਚਾਇ।","roman":"Raakas aae rohle kheti bhiran ke chaai |","meaning_en":"The wrathful demons came, eager to fight on the battlefield.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਲਸਕਨਿ ਤੇਗਾ ਬਰਛੀਆ ਸੂਰਜ ਨਦਰਿ ਨ ਪਾਇ। ੬।","roman":"Lasakni tegaa barchheeaa sooraj nadri na paai | 6 |","meaning_en":"Their swords and spears glittered so that the sun could not be seen. (6)","page":241,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਪਉੜੀ","gurmukhi":"ਪਉੜੀ","roman":"Pauree","meaning_en":"Pauri.","page":241,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":241,"lines":[{"gurmukhi":"ਦੁਹਾ ਕੰਧਾਰਾ ਮੁੰਹ ਜੁੜੇ ਢੋਲ ਸੰਖ ਨਗਾਰੇ ਬਜੇ।","roman":"Duhaa kandhaaraa munh jure dhol sankh nagaare baje |","meaning_en":"The two armies came face to face; drums, conches and kettledrums sounded.","page":241,"meaning_status":"draft","note":"ਕੰਧਾਰ: battle-line, army."},{"gurmukhi":"ਰਾਕਸ ਆਏ ਰੋਹਲੇ ਤਰਵਾਰੀ ਬਖਤਰ ਸਜੇ।","roman":"Raakas aae rohle tarvaaree bakhtar saje |","meaning_en":"The wrathful demons came, armed with swords and armour.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਜੁਟੇ ਸਉਹੇ ਜੁਧ ਨੋ ਇਕ ਜਾਤਿ ਨ ਜਾਣਨਿ ਭਜੇ।","roman":"Jute sauhe judh no ik jaati na jaanni bhaje |","meaning_en":"They faced each other and fought; not one of them knew how to flee.","page":241,"meaning_status":"draft","note":"ਇਕ ਜਾਤਿ: 'even once / not one'; read as 'they do not know flight at all'."},{"gurmukhi":"ਖੇਤ ਅੰਦਰ ਜੋਧੇ ਗਜੇ। ੭।","roman":"Khet andar jodhe gaje | 7 |","meaning_en":"The warriors roared on the battlefield. (7)","page":241,"meaning_status":"draft"}]},{"type":"verse","number":[8],"number_text":"੮।","page":241,"lines":[{"gurmukhi":"ਜੰਗ ਮੁਸਾਫਾ ਬਜਿਆ ਰਣਿ ਘੁਰੇ ਨਗਾਰੇ ਚਾਵਲੇ।","roman":"Jang musaaphaa bajiaa rani ghure nagaare chaavle |","meaning_en":"The war-drum sounded and the kettledrums thundered eagerly on the field.","page":241,"meaning_status":"draft","note":"ਜੰਗ ਮੁਸਾਫਾ: 'drum of war'; uncertain (musaafaa from Persian musaaf, 'battle'). ਚਾਵਲੇ: 'eager, spirited'; uncertain."},{"gurmukhi":"ਝੂਲਨਿ ਨੇਜੇ ਬੈਰਕਾ ਨੀਸਾਣ ਲਸਨਿ ਲਸਾਵਲੇ।","roman":"Jhoolni neje bairkaa neesaan lasni lasaavle |","meaning_en":"Lances and pennants swayed, and the bright standards glittered.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਢੋਲ ਨਗਾਰੇ ਪਉਣਦੇ ਊਘਨ ਜਾਣੁ ਜਟਾਵਲੇ।","roman":"Dhol nagaare paunde ooghan jaanu jataavle |","meaning_en":"Drums and kettledrums resounded; the warriors seemed like matted-haired ascetics nodding.","page":241,"meaning_status":"draft","note":"ਪਉਣਦੇ / ਊਘਨ: obscure; read as drums sounding and matted-haired (ascetics) drowsing/swaying; uncertain."},{"gurmukhi":"ਦੁਰਗਾ ਦਾਨੋ ਰਣਿ ਡਹੇ ਖੇਤ ਵਜਨਿ ਨਾਦ ਭੀਹਾਵਲੇ।","roman":"Durgaa daano rani dahe khet vajni naad bheehaavle |","meaning_en":"Durga and the demons engaged in battle; terrifying sounds rang out on the field.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਬੀਰ ਪ੍ਰੋਤੇ ਬ੍ਰਛੀਏ ਜਣੁ ਡਾਲ ਚਮੁਟੇ ਆਵਲੇ।","roman":"Beer prote brachhee'e janu daal chamute aavle |","meaning_en":"Warriors were pierced with spears, like fruit stuck to the branch of the amla tree.","page":241,"meaning_status":"draft","note":"ਆਵਲੇ: amla (Indian gooseberry) fruits."},{"gurmukhi":"ਇਕ ਵਢੇ ਤੇਗੀ ਤੜਫੀਅਨ ਮਦ ਪੀਤੇ ਲੋਟਨਿ ਬਾਵਲੇ।","roman":"Ik vadhe tegee tarpheean mad peete lotni baavle |","meaning_en":"Some, cut by swords, writhe, rolling about like madmen who have drunk wine.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਚੁਣਿ ਚੁਣਿ ਝਾੜਹੁ ਕਢੀਅਨ ਰੇਤ ਵਿਚੋ ਸੋਇਨਾ ਡਾਵਲੇ।","roman":"Ik chuni chuni jhaarhu kadheean ret vicho soinaa daavle |","meaning_en":"Some are picked out and pulled from the thicket, like gold being washed out of sand.","page":241,"meaning_status":"draft","note":"ਝਾੜਹੁ: from the bushes; ਡਾਵਲੇ: 'gold-washers'; uncertain."},{"gurmukhi":"ਗਦਾ ਤ੍ਰਿਸੂਲਾ ਬਰਛੀਆ ਤੀਰ ਵਗਨਿ ਖਰੇ ਉਤਾਵਲੇ।","roman":"Gadaa trisoolaa barchheeaa teer vagni khare utaavle |","meaning_en":"Maces, tridents, spears and arrows fly very swiftly.","page":241,"meaning_status":"draft"},{"gurmukhi":"ਜਣੁ ਡਸੇ ਭੁਯੰਗਮ ਸਾਵਲੇ ਮਰਿ ਜਾਵਨਿ ਬੀਰ ਰੋਹਾਵਲੇ। ੮।","roman":"Janu dase bhuyangam saavle mari jaavni beer rohaavle | 8 |","meaning_en":"Wrathful warriors die as if bitten by black serpents. (8)","page":241,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":242,"lines":[{"gurmukhi":"ਵੇਖਣ ਚੰਡਿ ਪ੍ਰਚੰਡ ਨੋ ਰਣਿ ਘੁਰੇ ਨਗਾਰੇ। ਧਾਏ ਰਾਕਸ ਰੋਹਲੇ ਚਉਗਿਰਦੇ ਭਾਰੇ।","roman":"Vekhan chandi prachand no rani ghure nagaare | dhaae raakas rohle chaugirde bhaare |","meaning_en":"To face fierce Chandi the kettledrums thundered on the field; mighty, wrathful demons rushed in from all four sides.","page":242,"meaning_status":"draft","note":"ਵੇਖਣ: 'to see/meet' Chandi; read as 'to confront'."},{"gurmukhi":"ਹਥੀ ਤੇਗਾ ਪਕੜਿਕੈ ਰਣਿ ਭਿੜੇ ਕਰਾਰੇ। ਕਦੇ ਨ ਨਠੈ ਜੁਧ ਤੇ ਜੋਧੇ ਜੁਝਾਰੇ।","roman":"Hathee tegaa pakrikai rani bhire karaare | kade na nathai judh te jodhe jujhaare |","meaning_en":"Gripping swords in their hands, they fought hard in battle; these warlike fighters never flee from war.","page":242,"meaning_status":"draft"},{"gurmukhi":"ਦਿਲ ਵਿਚ ਰੋਹ ਬਢਾਇ ਕੈ ਮਾਰੁ ਮਾਰੁ ਪੁਕਾਰੇ। ਮਾਰੇ ਚੰਡਿ ਪ੍ਰਚੰਡ ਨੈ ਬੀਰ ਖੇਤਿ ਉਤਾਰੇ।","roman":"Dil vich roh badhaai kai maaru maaru pukaare | maare chandi prachand nai beer kheti utaare |","meaning_en":"Swelling with rage in their hearts, they cried \"Kill! Kill!\" Fierce Chandi struck the warriors down on the field.","page":242,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰੇ ਜਾਪਨਿ ਬਿਜੁਲੀ ਸਿਰ ਭਾਰਿ ਮੁਨਾਰੇ। ੯।","roman":"Maare jaapni bijulee sir bhaari munaare | 9 |","meaning_en":"Struck down, they looked like minarets toppled headlong by lightning. (9)","page":242,"meaning_status":"draft","note":"ਮਾਰੇ ਬਿਜੁਲੀ: 'struck by lightning'; ਸਿਰ ਭਾਰਿ: headlong."}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":242,"lines":[{"gurmukhi":"ਚੋਟ ਪਈ ਦਮਾਮੇ ਦਲਾ ਮੁਕਾਬਲਾ। ਦੇਵੀ ਦਸਤਿ ਨਚਾਈ ਸੀਹਣਿ ਸਾਰ ਦੀ।","roman":"Chot paee damaame dalaa mukaablaa | devee dasti nachaaee seehni saar dee |","meaning_en":"The kettledrum was struck, the armies faced each other. The goddess made her steel lioness (sword) dance in her hand,","page":242,"meaning_status":"draft","note":"ਸੀਹਣਿ ਸਾਰ ਦੀ: 'lioness of steel', i.e. the sword."},{"gurmukhi":"ਪੇਟਿ ਮਲੰਦੇ ਲਾਈ ਮਹਿਖੇ ਦੈਤ ਨੋ। ਗੁਰਦੇ ਆਂਦਾ ਖਾਈ ਨਾਲ ਰੁਕੜੇ।","roman":"Peti malande laaee mahikhe dait no | gurde aandaa khaaee naal rukre |","meaning_en":"and drove it into the belly of the demon Mahishasur as he rubbed it; it ate through kidneys, intestines and ribs.","page":242,"meaning_status":"draft","note":"ਪੇਟਿ ਮਲੰਦੇ: 'into the belly of the one rubbing (it)'; uncertain; possibly 'into the belly of the wrestler'. ਰੁਕੜੇ: ribs; uncertain."},{"gurmukhi":"ਜੇਹੀ ਦਿਲ ਵਿਚ ਆਈ ਕਹੀ ਸੁਣਾਇਕੈ। ਚੋਟੀ ਜਾਣੁ ਦਿਖਾਈ ਤਾਰੇ ਧੂਮਕੇਤਿ। ੧੦।","roman":"Jehee dil vich aaee kahee sunaaikai | chotee jaanu dikhaaee taare dhoomketi | 10 |","meaning_en":"What came into my mind I have told: it was as if a comet had shown its tail. (10)","page":242,"meaning_status":"draft","note":"ਚੋਟੀ ... ਧੂਮਕੇਤਿ: the blade likened to the tail (crest) of a comet; uncertain."}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":242,"lines":[{"gurmukhi":"ਚੋਟਾ ਪਵਨਿ ਨਗਾਰੇ ਅਣੀਆ ਜੁਟੀਆ। ਧੂਹਿ ਲਈਆ ਤਰਵਾਰੀ ਦੇਵਾ ਦਾਨਵਾ।","roman":"Chotaa pavni nagaare aneeaa juteeaa | dhoohi laeeaa tarvaaree devaa daanvaa |","meaning_en":"Blows fell on the kettledrums and the vanguards clashed. Gods and demons drew their swords.","page":242,"meaning_status":"draft"},{"gurmukhi":"ਵਾਹਨਿ ਵਾਰੋ ਵਾਰੀ ਸੂਰੇ ਸੰਘਰੇ। ਵਗੈ ਰਤੁ ਝੁਲਾਰੀ ਜਿਉ ਗੇਰੂ ਬਾਬੁਤ੍ਰਾ।","roman":"Vaahni vaaro vaaree soore sanghre | vagai ratu jhulaaree jiu geroo baabutraa |","meaning_en":"Heroes strike again and again in the battle. Blood flows in streams like red ochre from the tunic.","page":242,"meaning_status":"draft","note":"ਬਾਬੁਤ੍ਰਾ: read as a garment (dyed with ochre); uncertain."},{"gurmukhi":"ਵੇਖਨਿ ਬੈਠਿ ਅਟਾਰੀ ਨਾਰੀ ਰਾਕਸਾ। ਪਾਈ ਧੂਮ ਸਵਾਰੀ ਦੁਰਗਾ ਦਾਨਵੀ। ੧੧।","roman":"Vekhni baithi ataaree naaree raaksaa | paaee dhoom savaaree durgaa daanvee | 11 |","meaning_en":"The demon women watch, seated on the balconies. Durga's riding made a stir among the demons. (11)","page":242,"meaning_status":"draft","note":"ਪਾਈ ਧੂਮ ਸਵਾਰੀ: 'her charge raised a commotion'; uncertain."}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":242,"lines":[{"gurmukhi":"ਲਖ ਨਗਾਰੇ ਵਜਨਿ ਆਮ੍ਹੋ ਸਾਹਮਣੇ। ਰਾਕਸ ਰਣਹੁੰ ਨ ਭਜਨਿ ਰੋਹੇ ਰੋਹਲੇ।","roman":"Lakh nagaare vajni aamho saahamne | raakas ranhun na bhajni rohe rohle |","meaning_en":"A hundred thousand kettledrums sound, facing each other. The wrathful demons, furious, do not flee the field.","page":242,"meaning_status":"draft"},{"gurmukhi":"ਸੀਹਾ ਵਾਗੂੰ ਗਜਣ ਸਭੇ ਸੂਰਮੇ। ਤਣਿ ਤਣਿ ਕੈਬਰ ਛਡਨਿ ਦੁਰਗਾ ਸਾਮ੍ਹਣੇ। ੧੨।","roman":"Seehaa vaagoon gajan sabhe soorme | tani tani kaibar chhadni durgaa saamhane | 12 |","meaning_en":"All the heroes roar like lions. They draw their bows to the full and loose arrows before Durga. (12)","page":242,"meaning_status":"draft","note":"ਕੈਬਰ: arrows."}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":242,"lines":[{"gurmukhi":"ਘੁਰੇ ਨਗਾਰੇ ਡੋਹਰੇ ਰਣਿ ਸੰਗਲੀਆਲੇ। ਧੂੜਿ ਲਪੇਟੇ ਧੂਹਰੇ ਸਰਦਾਰ ਜਟਾਲੇ।","roman":"Ghure nagaare dohre rani sangleeaale | dhoori lapete dhoohre sardaar jataale |","meaning_en":"Double-headed, chained kettledrums thundered on the field. Matted-haired chiefs were wrapped in dust.","page":242,"meaning_status":"draft","note":"ਡੋਹਰੇ / ਸੰਗਲੀਆਲੇ: 'doubled' and 'chained' drums; uncertain. ਧੂਹਰੇ: dust-covered; uncertain."},{"gurmukhi":"ਉਖਲੀਆ ਨਾਸਾ ਜਿਨਾ ਮੂੰਹਿ ਜਾਪਨ ਆਲੇ। ਧਾਏ ਦੇਵੀ ਸਾਮ੍ਹਣੇ ਬੀਰ ਮੁਛਲੀਆਲੇ।","roman":"Ukhleeaa naasaa jinaa moonhi jaapan aale | dhaae devee saamhane beer muchhleeaale |","meaning_en":"Their nostrils are like mortars and their mouths look like niches; mustachioed warriors rushed at the goddess.","page":242,"meaning_status":"draft","note":"ਉਖਲੀਆ: mortars (wide hollows). ਆਲੇ: wall-niches."},{"gurmukhi":"ਸੁਰਪਤਿ ਜੇਹੇ ਲੜਿ ਹਟੇ ਬੀਰ ਟਲੇ ਨ ਟਾਲੇ। ਗਜੇ ਦੁਰਗਾ ਘੇਰਿ ਕੈ ਜਣੁ ਘਣੀਅਰੁ ਕਾਲੇ। ੧੩।","roman":"Surapti jehe lari hate beer tale na taale | gaje durgaa gheri kai janu ghaneearu kaale | 13 |","meaning_en":"Warriors before whom even Indra, lord of gods, fought and withdrew, would not be turned back. They surrounded Durga and roared like black clouds. (13)","page":242,"meaning_status":"draft"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":242,"lines":[{"gurmukhi":"ਚੋਟ ਪਈ ਖਰਚਾਮੀ ਦਲਾ ਮੁਕਾਬਲਾ। ਘੇਰਿ ਲਈ ਵਰਿਆਮੀ ਦੁਰਗਾ ਆਇ ਕੈ।","roman":"Chot paee kharchaamee dalaa mukaablaa | gheri laee variaamee durgaa aai kai |","meaning_en":"The drum struck by the ass-hide stick sounded; the armies faced each other. The heroes came and surrounded Durga.","page":242,"meaning_status":"draft","note":"ਖਰਚਾਮੀ: 'of ass-hide' (khar = donkey, chaam = hide), describing the drum or drumstick; uncertain. ਵਰਿਆਮੀ: heroes."},{"gurmukhi":"ਰਾਖਸ ਬਡੈ ਅਲਾਮੀ ਭਜ ਨ ਜਾਣਦੇ। ਅੰਤਿ ਹੋਏ ਸੁਰਗਾਮੀ ਮਾਰੇ ਦੇਵਤਾ। ੧੪।","roman":"Raakhas badai alaamee bhaj na jaande | anti hoe surgaamee maare devtaa | 14 |","meaning_en":"The demons, great experts in war, do not know how to flee. In the end, killed by the goddess, they went to heaven. (14)","page":242,"meaning_status":"draft","note":"ਅਲਾਮੀ: 'learned, skilled' (Arabic 'allaama); uncertain. ਦੇਵਤਾ: here the goddess."}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":242,"lines":[{"gurmukhi":"ਅਗਣਤ ਘੁਰੇ ਨਗਾਰੇ ਦਲਾ ਭਿੜੰਦਿਆ। ਪਾਏ ਮਹਖਲ ਭਾਰੇ ਦੇਵਾ ਦਾਨਵਾ।","roman":"Agnat ghure nagaare dalaa bhirandiaa | paae mahkhal bhaare devaa daanvaa |","meaning_en":"Countless kettledrums thundered as the armies clashed. Gods and demons raised a great tumult.","page":242,"meaning_status":"draft","note":"ਮਹਖਲ: tumult, uproar; uncertain."},{"gurmukhi":"ਵਾਹਨਿ ਫਟ ਕਰਾਰੇ ਰਾਕਸ ਰੋਹਲੇ। ਜਾਪਨਿ ਤੇਗੀ ਆਰੇ ਮਿਆਨੋ ਧੂਹੀਆ।","roman":"Vaahni phat karaare raakas rohle | jaapni tegee aare miaano dhooheeaa |","meaning_en":"The wrathful demons strike hard blows. The swords drawn from the scabbards look like saws.","page":242,"meaning_status":"draft"},{"gurmukhi":"ਜੋਧੇ ਵਡੇ ਮੁਨਾਰੇ ਜਾਪਨ ਖੇਤ ਵਿਚ। ਦੇਵੀ ਆਪ ਸਵਾਰੇ ਪਬਾਂ ਜਵੇਹਣੇ।","roman":"Jodhe vade munaare jaapan khet vich | devee aap savaare pabaan javehne |","meaning_en":"The warriors look like great minarets on the field. The goddess herself destroyed those mountain-like ones.","page":243,"meaning_status":"draft","note":"ਪਬਾਂ ਜਵੇਹਣੇ: 'like hills / mountain peaks'; uncertain. ਸਵਾਰੇ: read as 'dispatched, killed'; uncertain."},{"gurmukhi":"ਕਦੇ ਨ ਆਖਨਿ ਹਾਰੇ ਧਾਵਨਿ ਸਾਮ੍ਹਣੇ। ਦੁਰਗਾ ਸਭੇ ਸੰਘਾਰੇ ਰਾਖਸ ਖੜਗ ਲੈ। ੧੫।","roman":"Kade na aakhni haare dhaavni saamhane | durgaa sabhe sanghaare raakhas kharag lai | 15 |","meaning_en":"They never said \"we are beaten\", but rushed forward; Durga, taking her sword, destroyed all the demons. (15)","page":243,"meaning_status":"draft"}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":243,"lines":[{"gurmukhi":"ਉਮਲ ਲਥੇ ਜੋਧੇ ਮਾਰੂ ਵਜਿਆ। ਬਦਲ ਜਿਉ ਮਹਿਖਾਸੁਰ ਰਣ ਵਿਚ ਗਜਿਆ।","roman":"Umal lathe jodhe maaroo vajiaa | badal jiu mahikhaasur ran vich gajiaa |","meaning_en":"The warriors surged forward; the war-music sounded. Like a cloud, Mahishasur thundered on the field:","page":243,"meaning_status":"draft","note":"ਉਮਲ ਲਥੇ: 'surged / poured in'; uncertain. ਮਾਰੂ: martial music."},{"gurmukhi":"ਇੰਦ੍ਰ ਜੇਹਾ ਜੋਧਾ ਮੈਥੋ ਭਜਿਆ। ਕਉਣ ਵਿਚਾਰੀ ਦਰਗਾ ਜਿਨਿ ਰਣ ਸਜਿਆ। ੧੬।","roman":"Indr jehaa jodhaa maitho bhajiaa | kaun vichaaree dargaa jini ran sajiaa | 16 |","meaning_en":"\"A warrior such as Indra fled from me; who is this wretched Durga who has prepared for battle?\" (16)","page":243,"meaning_status":"draft","note":"ਦਰਗਾ: printed so; read as ਦੁਰਗਾ."}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":243,"lines":[{"gurmukhi":"ਵਜੇ ਢੋਲ ਨਗਾਰੇ ਦਲਾ ਮੁਕਾਬਲਾ। ਤੀਰ ਫਿਰੈ ਰੈਬਾਰੇ ਆਮ੍ਹੋ ਸਾਮ੍ਹਣੇ।","roman":"Vaje dhol nagaare dalaa mukaablaa | teer phirai raibaare aamho saamhane |","meaning_en":"Drums and kettledrums sounded; the armies faced each other. Arrows flew like messengers back and forth.","page":243,"meaning_status":"draft","note":"ਰੈਬਾਰੇ: guides/messengers; uncertain."},{"gurmukhi":"ਅਗਣਤ ਬੀਰ ਸੰਘਾਰੇ ਲਗਦੀ ਕੈਬਰੀ। ਡਿਗੇ ਜਾਣ ਮੁਨਾਰੇ ਮਾਰੈ ਬਿਜੁ ਦੈ।","roman":"Agnat beer sanghaare lagdee kaibree | dige jaan munaare maarai biju dai |","meaning_en":"Countless warriors were killed as the arrows struck. They fell like minarets struck by lightning.","page":243,"meaning_status":"draft","note":"ਬਿਜੁ ਦੈ: 'by the lightning'."},{"gurmukhi":"ਖੁਲ੍ਹੀ ਵਾਲੀ ਦੈਤ ਅਹਾੜੇ ਸਭੇ ਸੂਰਮੇ। ਸੁਤੇ ਜਾਣੁ ਜਟਾਰੇ ਭੰਗਾ ਖਾਇ ਕੈ। ੧੭।","roman":"Khulhee vaalee dait ahaare sabhe soorme | sute jaanu jataare bhangaa khaai kai | 17 |","meaning_en":"With loosened hair, all the demon heroes lay in the battle, like matted-haired ascetics asleep after eating bhang. (17)","page":243,"meaning_status":"draft","note":"ਅਹਾੜੇ: read as 'lay (in battle)', from ahaar = fight; uncertain."}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":243,"lines":[{"gurmukhi":"ਦੁਹਾ ਕੰਧਾਰਾ ਮੁੰਹ ਜੁੜੇ ਨਾਲ ਧਉਸਾ ਭਾਰੀ।","roman":"Duhaa kandhaaraa munh jure naal dhausaa bhaaree |","meaning_en":"The two armies came face to face with the heavy war-drum sounding.","page":243,"meaning_status":"draft","note":"ਧਉਸਾ: large kettledrum."},{"gurmukhi":"ਕੜਕਿ ਉਠਿਆ ਫਉਜ ਤੇ ਵਡਾ ਹੰਕਾਰੀ।","roman":"Karki uthiaa phauj te vadaa hankaaree |","meaning_en":"Out of the army, the great proud one rose up with a roar.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕੈ ਚਲਿਆ ਸੂਰਮੇ ਨਾਲਿ ਵਡੇ ਹਜਾਰੀ।","roman":"Lai kai chaliaa soorme naali vade hajaaree |","meaning_en":"He went forward taking heroes with him, great commanders of thousands.","page":243,"meaning_status":"draft","note":"ਹਜਾਰੀ: commanders of a thousand."},{"gurmukhi":"ਮਿਆਨੋ ਖੰਡਾ ਧੂਹਿਆ ਮਹਿਖਾਸੁਰ ਭਾਰੀ।","roman":"Miaano khandaa dhoohiaa mahikhaasur bhaaree |","meaning_en":"The mighty Mahishasur drew the double-edged sword from its scabbard.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਉਮਲ ਲਥੇ ਸੂਰਮੇ ਮਾਰ ਮਚੀ ਕਰਾਰੀ।","roman":"Umal lathe soorme maar machee karaaree |","meaning_en":"The heroes surged forward and fierce slaughter broke out.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਚਲੇ ਜਾਪਨਿ ਰਤ ਦੇ ਸਲਲੇ ਜਟਧਾਰੀ। ੧੮।","roman":"Chale jaapni rat de salle jatdhaaree | 18 |","meaning_en":"The blood flowing looked like the water flowing from Shiva's matted hair. (18)","page":243,"meaning_status":"draft","note":"ਸਲਲੇ ਜਟਧਾਰੀ: 'the waters of the matted-haired one', i.e. the Ganga from Shiva's locks; uncertain."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":243,"lines":[{"gurmukhi":"ਸਟ ਪਈ ਜਮਧਾਣੀ ਦਲਾ ਮੁਕਾਬਲਾ।","roman":"Sat paee jamdhaanee dalaa mukaablaa |","meaning_en":"The drum of Yama was struck; the armies faced each other.","page":243,"meaning_status":"draft","note":"ਜਮਧਾਣੀ: read as the drum (of death/Yama); uncertain."},{"gurmukhi":"ਧੂਹਿ ਲਈ ਕਿਰਪਾਣੀ ਦੁਰਗਾ ਮਿਆਨ ਤੇ।","roman":"Dhoohi laee kirpaanee durgaa miaan te |","meaning_en":"Durga drew her sword from the scabbard.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡੀ ਰਾਕਸ ਖਾਣੀ ਵਾਹੀ ਦੈਤ ਨੂੰ।","roman":"Chandee raakas khaanee vaahee dait noon |","meaning_en":"Chandi, devourer of demons, struck the demon with it.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪਰ ਚੂਰਿ ਚਵਾਣੀ ਲਥੀ ਕਰਗ ਲੈ।","roman":"Kopar choori chavaanee lathee karag lai |","meaning_en":"It shattered the skull and face and went down through the skeleton,","page":243,"meaning_status":"draft","note":"ਕੋਪਰ: skull. ਚਵਾਣੀ: read as jaw/face; ਕਰਗ: skeleton/body; uncertain."},{"gurmukhi":"ਪਾਖਰ ਤੁਰਾ ਪਲਾਣੀ ਰੜਕੀ ਧਰਤਿ ਜਾਇ।","roman":"Paakhar turaa palaanee rarkee dharti jaai |","meaning_en":"through the saddle, the horse and its armour, and struck into the earth.","page":243,"meaning_status":"draft","note":"ਪਾਖਰ: horse-armour. ਰੜਕੀ: struck, grated."},{"gurmukhi":"ਲੈਦੀ ਅਘਾ ਸਿਧਾਣੀ ਸਿੰਗਾ ਧਉਲ ਦਿਆ।","roman":"Laidee aghaa sidhaanee singaa dhaul diaa |","meaning_en":"Going on further, it reached the horns of the bull (that holds the earth),","page":243,"meaning_status":"draft","note":"ਅਘਾ ਸਿਧਾਣੀ: 'went further'; ਧਉਲ: the mythic bull supporting the earth."},{"gurmukhi":"ਕੂਰਮ ਸਿਰ ਲਹਲਾਣੀ ਦੁਸਮਨ ਮਾਰ ਕੈ।","roman":"Kooram sir lahlaanee dusman maar kai |","meaning_en":"and struck the head of the tortoise (beneath), having killed the enemy.","page":243,"meaning_status":"draft","note":"ਕੂਰਮ: the mythic tortoise. ਲਹਲਾਣੀ: read as 'reached/flashed on'; uncertain."},{"gurmukhi":"ਵਢੇ ਗੰਨ ਤਿਖਾਣੀ ਮੂਏ ਖੇਤ ਵਿਚ।","roman":"Vadhe gann tikhaanee mooe khet vich |","meaning_en":"The slain lay on the field like logs cut by a carpenter.","page":243,"meaning_status":"draft","note":"ਗੰਨ: logs, beams; uncertain."},{"gurmukhi":"ਰਣ ਵਿਚ ਘਤੀ ਘਾਣੀ ਲੋਹੂ ਮਿਝ ਦੀ।","roman":"Ran vich ghatee ghaanee lohoo mijh dee |","meaning_en":"On the field she made a press of blood and marrow.","page":243,"meaning_status":"draft","note":"ਘਾਣੀ: a press-load (as in an oil-press)."},{"gurmukhi":"ਚਾਰੇ ਜੁਗ ਕਹਾਣੀ ਚਲਗਿ ਤੇਗ ਦੀ।","roman":"Chaare jug kahaanee chalgi teg dee |","meaning_en":"The tale of the sword will be told through all four ages.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਵਿਧਣ ਖੇਤਿ ਵਿਹਾਣੀ ਮਹਿਖੇ ਦੈਤ ਨੂੰ।੧੯।","roman":"Vidhan kheti vihaanee mahikhe dait noon | 19 |","meaning_en":"On the field, calamity came upon the demon Mahishasur. (19)","page":243,"meaning_status":"draft","note":"ਵਿਧਣ: hardship, calamity."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":243,"lines":[{"gurmukhi":"ਇਤੀ ਮਹਿਖਾਸੁਰ ਦੈਤ ਮਾਰੇ ਦੁਰਗਾ ਆਇਆ।","roman":"Itee mahikhaasur dait maare durgaa aaiaa |","meaning_en":"Thus, having killed the demon Mahishasur, Durga came,","page":243,"meaning_status":"draft","note":"ਇਤੀ: 'thus / in this way'; uncertain. ਆਇਆ: printed so (masculine form)."},{"gurmukhi":"ਚਉਦਹ ਲੋਕਾਂ ਰਾਣੀ ਸਿੰਘ ਨਚਾਇਆ।","roman":"Chaudah lokaan raanee singh nachaaiaa |","meaning_en":"the queen of the fourteen worlds, making her lion dance.","page":243,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰੇ ਵੀਰ ਜਟਾਣੀ ਦਲ ਵਿਚਿ ਅਗਲੇ।","roman":"Maare veer jataanee dal vichi agle |","meaning_en":"She killed the matted-haired heroes who were in the front of the army,","page":244,"meaning_status":"draft","note":"ਜਟਾਣੀ: matted-haired; ਅਗਲੇ: in the front ranks."},{"gurmukhi":"ਮੰਗਣ ਨਾਹੀ ਪਾਣੀ ਦਲੀ ਹੰਕਾਰਿ ਕੈ ।","roman":"Mangan naahee paanee dalee hankaari kai |","meaning_en":"who in their pride, among the armies, did not even ask for water;","page":244,"meaning_status":"draft"},{"gurmukhi":"ਜਣੁ ਕਰੀ ਸਮਾਇ ਪਠਾਣੀ ਸੁਣਿ ਕੈ ਰਾਗੁ ਨੂੰ।","roman":"Janu karee samaai pathaanee suni kai raagu noon |","meaning_en":"as if Pathans, hearing music, had fallen into a trance.","page":244,"meaning_status":"draft","note":"ਕਰੀ ਸਮਾਇ: read as 'went into ecstasy / a trance'; uncertain."},{"gurmukhi":"ਰਤੁ ਦੇ ਹੜ੍ਹਵਾਣੀ ਚਲੇ ਬੀਰ ਖੇਤ।","roman":"Ratu de harhavaanee chale beer khet |","meaning_en":"Floods of blood flowed from the warriors on the field,","page":244,"meaning_status":"draft","note":"ਹੜ੍ਹਵਾਣੀ: floods."},{"gurmukhi":"ਪੀਤਾ ਫੁਲ ਅਯਾਣੀ ਘੂਮਣਿ ਸੂਰਮੇ।੨੦।","roman":"Peetaa phul ayaanee ghoomni soorme | 20 |","meaning_en":"and the heroes reel like those who have unknowingly drunk the poppy-flower. (20)","page":244,"meaning_status":"draft","note":"ਪੀਤਾ ਫੁਲ ਅਯਾਣੀ: 'drunk the flower (an intoxicant) unknowingly'; uncertain."}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":244,"lines":[{"gurmukhi":"ਹੋਈ ਲੋਪ ਭਵਾਨੀ ਦੇਵਾ ਨੂੰ ਰਾਜੁ ਦੇ। ਈਸਰ ਦੀ ਬਰਦਾਨੀ ਹੋਈ ਜਿਤੁ ਦਿਨ।","roman":"Hoee lop bhavaanee devaa noon raaju de | eesar dee bardaanee hoee jitu din |","meaning_en":"Bhavani vanished, having given the kingdom to the gods. On the day that Shiva granted a boon,","page":244,"meaning_status":"draft","note":"ਈਸਰ ਦੀ ਬਰਦਾਨੀ: Shiva's granting of a boon (to the demons)."},{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਗੁਮਾਨੀ ਜਨਮੇ ਸੂਰਮੇ। ਇੰਦ੍ਰ ਦੀ ਰਾਜਧਾਨੀ ਤਕੀ ਜਿਤਣੀ। ੨੧।","roman":"Sunbh nisunbh gumaanee janme soorme | indr dee raajdhaanee takee jitnee | 21 |","meaning_en":"the proud heroes Sumbh and Nisumbh were born. They set their sights on conquering Indra's capital. (21)","page":244,"meaning_status":"draft"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":244,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਪੁਰੀ ਤੇ ਧਾਵਣਾ ਵਡ ਜੋਧੀ ਮਤਾ ਪਕਾਇਆ।","roman":"Indr puree te dhaavnaa vad jodhee mataa pakaaiaa |","meaning_en":"The great warriors made a plan to march on Indra's city.","page":244,"meaning_status":"draft"},{"gurmukhi":"ਸੰਜ ਪਟੇਲਾ ਪਾਖਰਾ ਭੇੜ ਸੰਦਾ ਸਾਜੁ ਬਣਾਇਆ।","roman":"Sanj patelaa paakhraa bher sandaa saaju banaaiaa |","meaning_en":"They made ready the gear of battle: coats of mail, belts and horse-armour.","page":244,"meaning_status":"draft","note":"ਸੰਜ: coat of mail. ਪਟੇਲਾ: read as armour-belts or plated armour; uncertain. ਪਾਖਰ: horse-armour."},{"gurmukhi":"ਜੁੰਮੇ ਕਟਕ ਅਛੂਹਣੀ ਅਸਮਾਨ ਗਰਦੈ ਛਾਇਆ।","roman":"Junme katak achhoohnee asmaan gardai chhaaiaa |","meaning_en":"An army of akshauhinis gathered, and its dust spread over the sky.","page":244,"meaning_status":"draft","note":"ਅਛੂਹਣੀ: akshauhini, a great army division. ਜੁੰਮੇ: gathered, set out."},{"gurmukhi":"ਰੋਹਿ ਸੁੰਭ ਨਿਸੁੰਭ ਸਿਧਾਇਆ। ੨੨।","roman":"Rohi sunbh nisunbh sidhaaiaa | 22 |","meaning_en":"In wrath Sumbh and Nisumbh set out. (22)","page":244,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":244,"lines":[{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਅਲਾਇਆ ਵਡ ਜੋਧੀ ਸੰਘਰ ਵਾਏ।","roman":"Sunbh nisunbh alaaiaa vad jodhee sanghar vaae |","meaning_en":"Sumbh and Nisumbh called out, and the great warriors sounded the battle-drums.","page":244,"meaning_status":"draft","note":"ਅਲਾਇਆ: called out, gave the order."},{"gurmukhi":"ਰੋਹ ਦਿਖਾਲੀ ਦਿਤੀਆ ਵਰਿਆਮੀ ਤੁਰੇ ਨਚਾਏ।","roman":"Roh dikhaalee diteeaa variaamee ture nachaae |","meaning_en":"They showed their wrath; the heroes made their horses dance.","page":244,"meaning_status":"draft"},{"gurmukhi":"ਘੁਰੇ ਦਮਾਮੇ ਦੋਹਰੇ ਜਮ ਬਾਹਣ ਜਿਉ ਅਰੜਾਏ।","roman":"Ghure damaame dohre jam baahan jiu arraae |","meaning_en":"The double kettledrums thundered, roaring like the buffalo, mount of Yama.","page":244,"meaning_status":"draft","note":"ਜਮ ਬਾਹਣ: the buffalo, Yama's mount."},{"gurmukhi":"ਦੇਉ ਦਾਨੋ ਲੁਝਣ ਆਏ। ੨੩।","roman":"Deu daano lujhan aae | 23 |","meaning_en":"Gods and demons came to fight. (23)","page":244,"meaning_status":"draft"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":244,"lines":[{"gurmukhi":"ਦਾਨੋ ਦੇਉ ਅਨਾਗੀ ਸੰਘਰੁ ਰਚਿਆ। ਫੁਲ ਖਿੜੇ ਜਣੁ ਬਾਗੀ ਬਾਣੈ ਜੋਧਿਆ।","roman":"Daano deu anaagee sanghru rachiaa | phul khire janu baagee baanai jodhiaa |","meaning_en":"Demons and gods arrayed a relentless battle. The warriors in their garments were like flowers blooming in a garden.","page":244,"meaning_status":"draft","note":"ਅਨਾਗੀ: 'unbroken, relentless'; uncertain."},{"gurmukhi":"ਭੂਤਾ ਇਲਾ ਕਾਗੀ ਗੋਸਤ ਭਖਿਆ। ਹੁਮੜ ਧੁਮੜ ਜਾਗੀ ਘਤੀ ਸੂਰਿਆ। ੨੪।","roman":"Bhootaa ilaa kaagee gosat bhakhiaa | humar dhumar jaagee ghatee sooriaa | 24 |","meaning_en":"Ghosts, kites and crows ate the flesh. The heroes raised a great clamour. (24)","page":244,"meaning_status":"draft","note":"ਇਲਾ: kites (birds). ਹੁਮੜ ਧੁਮੜ: sound-word for tumult; left as 'great clamour'."}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":244,"lines":[{"gurmukhi":"ਸਟ ਪਈ ਨਗਾਰੇ ਦਲਾ ਮੁਕਾਬਲਾ। ਦਿਤੇ ਦੇਉ ਭਜਾਈ ਮਿਲ ਕੈ ਰਾਕਸੀ।","roman":"Sat paee nagaare dalaa mukaablaa | dite deu bhajaaee mil kai raaksee |","meaning_en":"Blows fell on the kettledrums; the armies faced each other. The demons together put the gods to flight.","page":244,"meaning_status":"draft","note":"ਭਜਾਈ: printed so; 'put to flight'."},{"gurmukhi":"ਲੋਕੀ ਤਿਹੀ ਫਿਰਾਹੀ ਦੋਹੀ ਆਪਣੀ। ਦੁਰਗਾ ਦੀ ਸਾਮ ਤਕਾਈ ਦੇਵਾ ਡਰਦਿਆ।","roman":"Lokee tihee phiraahee dohee aapnee | durgaa dee saam takaaee devaa dardiaa |","meaning_en":"They proclaimed their own rule in the three worlds. The gods, afraid, looked to Durga for shelter.","page":244,"meaning_status":"draft"},{"gurmukhi":"ਆਦੀ ਚੰਡਿ ਚੜਾਈ ਉਤੇ ਰਾਕਸਾ। ੨੫।","roman":"Aadee chandi charaaee ute raaksaa | 25 |","meaning_en":"They brought Chandi to march against the demons. (25)","page":244,"meaning_status":"draft","note":"ਆਦੀ: read as 'brought' (aandi); uncertain; could also be 'the Primal' (aadi)."}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":244,"lines":[{"gurmukhi":"ਆਈ ਫੇਰਿ ਭਵਾਨੀ ਖਬਰੀ ਪਾਈਆ। ਦੈਤ ਵਡੇ ਅਭਿਮਾਨੀ ਹੋਏ ਇਕਠੇ।","roman":"Aaee pheri bhavaanee khabree paaeeaa | dait vade abhimaanee hoe ikthe |","meaning_en":"Bhavani came again; the news spread. The very proud demons gathered together.","page":244,"meaning_status":"draft"},{"gurmukhi":"ਲੋਚਨ ਧੂਮ ਗੁਮਾਨੀ ਰਾਇ ਬੁਲਾਇਆ। ਵਡਾ ਜਗ ਵਿਚ ਦਾਨੋ ਆਪ ਕਹਾਇਆ।","roman":"Lochan dhoom gumaanee raai bulaaiaa | vadaa jag vich daano aap kahaaiaa |","meaning_en":"The king called the proud Dhumar Lochan, who had himself called the greatest demon in the world.","page":244,"meaning_status":"draft","note":"ਲੋਚਨ ਧੂਮ: Dhumar Lochan (Dhumralochan)."},{"gurmukhi":"ਚੋਟ ਪਈ ਖਰਚਾਮੀ ਦੁਰਗਾ ਲਿਆਵਣੀ। ੨੬।","roman":"Chot paee kharchaamee durgaa liaavnee | 26 |","meaning_en":"The drum of ass-hide was struck to bring Durga in. (26)","page":244,"meaning_status":"draft","note":"ਖਰਚਾਮੀ: 'of ass-hide'; see note at 1.18.0; uncertain."}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":244,"lines":[{"gurmukhi":"ਕੜਕਿ ਉਠੀ ਰਣਿ ਚੰਡੀ ਫਉਜਾ ਦੇਖਿ ਕੈ। ਧੂਹਿ ਮਿਆਨੋ ਖੰਡਾ ਧਾਈ ਸਾਮ੍ਹਣੇ।","roman":"Karki uthee rani chandee phaujaa dekhi kai | dhoohi miaano khandaa dhaaee saamhane |","meaning_en":"Seeing the armies, Chandi rose with a roar on the field. Drawing the double-edged sword from its scabbard, she rushed at them.","page":244,"meaning_status":"draft"},{"gurmukhi":"ਸਭੇ ਬੀਰ ਸੰਘਾਰੇ ਧੂਮਰ ਨੈਣ ਦੇ। ਜਣੁ ਲੈ ਕਟੇ ਆਰੇ ਦਰਖਤ ਬਾਢੀਆ। ੨੭।","roman":"Sabhe beer sanghaare dhoomar nain de | janu lai kate aare darkhat baadheeaa | 27 |","meaning_en":"She destroyed all of Dhumar Nain's warriors, as if carpenters had cut down trees with saws. (27)","page":244,"meaning_status":"draft","note":"ਧੂਮਰ ਨੈਣ: another name for Dhumar Lochan."}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":245,"lines":[{"gurmukhi":"ਚੋਬੀ ਧਉਸ ਵਜਾਈ ਦਲਾ ਮੁਕਾਬਲਾ। ਰੋਹਿ ਭਵਾਨੀ ਆਈ ਉਤੈ ਰਾਖਸਾ।","roman":"Chobee dhaus vajaaee dalaa mukaablaa | rohi bhavaanee aaee utai raakhsaa |","meaning_en":"The drummers beat the kettledrum; the armies faced each other. Bhavani came in wrath upon the demons.","page":245,"meaning_status":"draft","note":"ਚੋਬੀ: drummers (those with the drumstick)."},{"gurmukhi":"ਖਬੇ ਦਸਤ ਨਚਾਈ ਸੀਹਣ ਸਾਰ ਦੀ। ਬਹੁਤਿਆ ਦੇ ਤਨਿ ਲਾਈ ਕੀਤੀ ਰੰਗੁਲੀ।","roman":"Khabe dasat nachaaee seehan saar dee | bahutiaa de tani laaee keetee rangulee |","meaning_en":"She made the steel lioness (sword) dance in her left hand. She drove it into many bodies and dyed it red.","page":245,"meaning_status":"draft","note":"ਰੰਗੁਲੀ: coloured, i.e. reddened with blood."},{"gurmukhi":"ਭਾਈਆ ਮਾਰਨਿ ਭਾਈ ਦੁਰਗਾ ਜਾਣਿ ਕੈ। ਰੋਹੈ ਹੋਇ ਚਲਾਈ ਰਾਕਸਿ ਰਾਇ ਨੋ।","roman":"Bhaaeeaa maarni bhaaee durgaa jaani kai | rohai hoi chalaaee raaksi raai no |","meaning_en":"Thinking them to be Durga, brothers killed brothers. In wrath she struck at the demon king,","page":245,"meaning_status":"draft"},{"gurmukhi":"ਜਮਪੁਰਿ ਦੀਆ ਪਠਾਈ ਲੋਚਨਧੂਮ ਨੋ। ਜਾਪੇ ਦਿਤੀ ਸਾਈ ਮਾਰਣ ਸੁੰਭ ਦੀ। ੨੮।","roman":"Jampuri deeaa pathaaee lochandhoom no | jaape ditee saaee maaran sunbh dee | 28 |","meaning_en":"and sent Dhumar Lochan to the city of Yama. It seemed she had given the earnest-money for killing Sumbh. (28)","page":245,"meaning_status":"draft","note":"ਸਾਈ: earnest-money, advance (paid to seal a bargain)."}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":245,"lines":[{"gurmukhi":"ਭੰਨੇ ਦੈਤ ਪੁਕਾਰੇ ਰਾਜੇ ਸੁੰਭ ਥੈ। ਲੋਚਨ ਧੂਮ ਸੰਘਾਰੇ ਸਣੇ ਸਿਪਾਹੀਆ।","roman":"Bhanne dait pukaare raaje sunbh thai | lochan dhoom sanghaare sane sipaaheeaa |","meaning_en":"The routed demons cried out to King Sumbh: \"Dhumar Lochan has been destroyed together with his soldiers.","page":245,"meaning_status":"draft","note":"ਥੈ: to, before."},{"gurmukhi":"ਚੁਣਿ ਚੁਣਿ ਜੋਧੇ ਮਾਰੇ ਅੰਦਰ ਖੇਤ ਦੈ। ਜਾਪਨਿ ਅੰਬਰਿ ਤਾਰੇ ਡਿਗਨਿ ਸੂਰਮੇ।","roman":"Chuni chuni jodhe maare andar khet dai | jaapni anbri taare digni soorme |","meaning_en":"She picked out the warriors one by one and killed them on the field; the heroes fall like stars from the sky.","page":245,"meaning_status":"draft"},{"gurmukhi":"ਗਿਰੇ ਪਰਬਤ ਭਾਰੇ ਮਾਰੇ ਬ੍ਰਿਜੁ ਦੇ। ਦੈਤਾ ਦੇ ਦਲ ਹਾਰੇ ਦਹਸਤ ਖਾਇ ਕੈ।","roman":"Gire parbat bhaare maare briju de | daitaa de dal haare dahsat khaai kai |","meaning_en":"They fell like great mountains struck by lightning; the demon armies, gripped by terror, were defeated.","page":245,"meaning_status":"draft","note":"ਬ੍ਰਿਜੁ: printed so; read as ਬਿਜੁ, lightning. ਦਹਸਤ: terror (Persian dahshat)."},{"gurmukhi":"ਬਚੇ ਸੁ ਮਾਰੇ ਮਾਰੇ ਰਹਦੇ ਰਾਇ ਥੈ। ੨੯।","roman":"Bache su maare maare rahde raai thai | 29 |","meaning_en":"Those who survived were killed again and again; only those who stayed with the king remained.\" (29)","page":245,"meaning_status":"draft","note":"ਬਚੇ ਸੁ ਮਾਰੇ ਮਾਰੇ ਰਹਦੇ ਰਾਇ ਥੈ: obscure; read as above; possibly 'those who escaped, half-dead, came to the king'; uncertain."}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":245,"lines":[{"gurmukhi":"ਰੋਹੈ ਹੋਇ ਬੁਲਾਏ ਰਾਕਸ ਸੁੰਭ ਨੈ। ਬੈਠੇ ਮਤਾ ਪਕਾਏ ਦੇਵੀ ਲਿਆਵਣੀ।","roman":"Rohai hoi bulaae raakas sunbh nai | baithe mataa pakaae devee liaavnee |","meaning_en":"In wrath Sumbh called the demons. They sat and resolved to bring the goddess.","page":245,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡ ਅਰੁ ਮੁੰਡ ਪਠਾਏ ਬਹੁਤਾ ਕਟਕ ਦੈ। ਜਾਪੇ ਛਪਰ ਛਾਏ ਬਣੀਆ ਕੇਜਮਾ।","roman":"Chand aru mund pathaae bahutaa katak dai | jaape chhapar chhaae baneeaa kejmaa |","meaning_en":"He sent Chand and Mund, giving them a great army. Their lances looked like thatched roofs.","page":245,"meaning_status":"draft","note":"ਕੇਜਮਾ: lances, spears (tents of spears like thatch); uncertain."},{"gurmukhi":"ਜੇਤੇ ਰਾਇ ਬੁਲਾਇ ਚਲੇ ਜੁਧ ਨੋ। ਜਣੁ ਜਮਿ ਪਕੜਿ ਚਲਾਏ ਸਭੇ ਮਾਰਣੇ। ੩੦।","roman":"Jete raai bulaai chale judh no | janu jami pakri chalaae sabhe maarne | 30 |","meaning_en":"All the kings who were called went to war, as if Yama had seized them and sent them all to be killed. (30)","page":245,"meaning_status":"draft","note":"ਬੁਲਾਇ: printed so (ਬੁਲਾਏ)."}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":245,"lines":[{"gurmukhi":"ਢੋਲ ਨਗਾਰੇ ਵਾਏ ਦਲਾ ਮੁਕਾਬਲਾ। ਰੋਹਿ ਰੁਹੇਲੇ ਆਏ ਉਤੇ ਰਾਕਸਾ।","roman":"Dhol nagaare vaae dalaa mukaablaa | rohi ruhele aae ute raaksaa |","meaning_en":"Drums and kettledrums sounded; the armies faced each other. The wrathful warriors came upon the demons.","page":245,"meaning_status":"draft","note":"ਰੋਹਿ ਰੁਹੇਲੇ: 'wrathful Rohillas' or simply 'the wrathful ones'; uncertain. Here 'the demons' (ਰਾਕਸਾ) suggests the goddess's side came upon them; uncertain."},{"gurmukhi":"ਸਭਨੀ ਤੁਰੇ ਨਚਾਏ ਬਰਛੇ ਪਕੜਿ ਕੇ । ਬਹੁਤੇ ਮਾਰਿ ਗਿਰਾਏ ਅੰਦਰਿ ਖੇਤ ਦੈ।","roman":"Sabhnee ture nachaae barchhe pakri ke | bahute maari giraae andri khet dai |","meaning_en":"They all made their horses dance, holding spears; many were struck down on the field.","page":245,"flags":[{"code":"space","reason":"word space printed as a gap (5.5pt), space inserted"}],"meaning_status":"draft"},{"gurmukhi":"ਤੀਰੀ ਛਹਬਰ ਲਾਏ ਬੁਠੀ ਦੇਵਤਾ। ੩੧।","roman":"Teeree chhahbar laae buthee devtaa | 31 |","meaning_en":"The goddess poured down a shower of arrows. (31)","page":245,"meaning_status":"draft","note":"ਬੁਠੀ: rained, showered. ਦੇਵਤਾ: here the goddess."}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":245,"lines":[{"gurmukhi":"ਭੇਰੀ ਸੰਖ ਬਜਾਏ ਸੰਘਰ ਰਚਿਆ । ਤਣਿ ਤਣਿ ਤੀਰ ਚਲਾਏ ਦੁਰਗਾ ਧਨੁਖ ਲੈ।","roman":"Bheree sankh bajaae sanghar rachiaa | tani tani teer chalaae durgaa dhanukh lai |","meaning_en":"Kettledrums and conches sounded and battle was joined. Durga, taking her bow, drew and loosed arrows.","page":245,"flags":[{"code":"space","reason":"word space printed as a gap (5.5pt), space inserted"}],"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ੍ਹੀ ਦਸਤ ਉਠਾਏ ਰਹੇ ਨ ਜੀਵਦੇ। ਚੰਡ ਅਰੁ ਮੁੰਡ ਖਪਾਏ ਦੋਨੋ ਦੇਵਤਾ । ੩੨।","roman":"Jinhee dasat uthaae rahe na jeevde | chand aru mund khapaae dono devtaa | 32 |","meaning_en":"Those who raised their hands did not remain alive. The goddess destroyed both Chand and Mund. (32)","page":245,"flags":[{"code":"space","reason":"word space printed as a gap (6.5pt), space inserted"}],"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":245,"lines":[{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਰਿਸਾਏ ਮਾਰੇ ਦੈਤ ਸੁਣਿ। ਜੋਧੇ ਸਭੈ ਬੁਲਾਏ ਆਪਣੀ ਮਜਲਸੈ।","roman":"Sunbh nisunbh risaae maare dait suni | jodhe sabhai bulaae aapnee majalsai |","meaning_en":"Hearing that the demons were killed, Sumbh and Nisumbh grew angry. They called all the warriors to their assembly:","page":245,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ੍ਹੀ ਦੈਵ ਭਜਾਏ ਇੰਦ੍ਰ ਜੇਵਹੇ। ਤੇਈ ਮਾਰਿ ਗਿਰਾਏ ਪਲ ਵਿਚ ਦੇਵਤੇ।","roman":"Jinhee daiv bhajaae indr jevhe | te'ee maari giraae pal vich devte |","meaning_en":"\"Those who put to flight gods such as Indra, the goddess struck down in a moment.\"","page":245,"meaning_status":"draft","note":"ਦੈਵ: printed so; read as ਦੇਵ, gods. ਦੇਵਤੇ: here the goddess."},{"gurmukhi":"ਦਸਤੀ ਦਸਤ ਵਜਾਏ ਉਨ੍ਹਾ ਚਿਤ ਕਰਿ। ਫਿਰ ਸ੍ਰਣਵਤ ਬੀਜ ਚਲਾਏ ਬੀੜੇ ਰਾਇ ਦੇ।","roman":"Dastee dasat vajaae unhaa chit kari | phir sranvat beej chalaae beere raai de |","meaning_en":"Thinking of them, they struck hand on hand. Then Raktabij was sent, accepting the king's betel-leaf.","page":246,"meaning_status":"draft","note":"ਸ੍ਰਣਵਤ ਬੀਜ: Shronavat Bij, i.e. Raktabij ('blood-seed'). ਬੀੜੇ ਰਾਇ ਦੇ: the king's betel-leaf, taken as a pledge to undertake the mission."},{"gurmukhi":"ਸੰਜ ਪਟੈਲਾ ਪਾਏ ਚਿਲਕਤ ਟੋਪੀਆ। ਲੁਝਣ ਨੂੰ ਅਰੜਾਏ ਰਾਕਸ ਰੋਹਲੇ।","roman":"Sanj patailaa paae chilkat topeeaa | lujhan noon arraae raakas rohle |","meaning_en":"They put on mail and armour, with gleaming helmets; the wrathful demons roared to fight.","page":246,"meaning_status":"draft","note":"ਟੋਪੀਆ: helmets."},{"gurmukhi":"ਕਿਨੈ ਨ ਕਦੇ ਹਟਾਏ ਜੁਧ ਮਚਾਇਕੈ। ਮਿਲਿ ਤੇਈ ਦਾਨੋ ਆਏ ਹੁਣ ਸੰਘਰ ਵੇਖਣਾ। ੩੩।","roman":"Kinai na kade hataae judh machaaikai | mili te'ee daano aae hun sanghar vekhnaa | 33 |","meaning_en":"No one had ever turned them back once they joined battle; those very demons have now come together: now see the battle! (33)","page":246,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":246,"lines":[{"gurmukhi":"ਦੈਤੀ ਡੰਡ ਉਭਾਰੀ ਨੇੜੇ ਆਇਕੈ। ਸਿੰਘ ਕਰੀ ਅਸਵਾਰੀ ਦੁਰਗਾ ਸੋਰ ਸੁਣਿ।","roman":"Daitee dand ubhaaree nere aaikai | singh karee asvaaree durgaa sor suni |","meaning_en":"The demons came near and raised a din. Hearing the noise, Durga mounted her lion.","page":246,"meaning_status":"draft","note":"ਡੰਡ ਉਭਾਰੀ: 'raised a clamour'; uncertain."},{"gurmukhi":"ਖਬੇ ਦਸਤ ਉਭਾਰੀ ਗਦਾ ਫਿਰਾਇ ਕੈ। ਸੈਨਾ ਸਭ ਸੰਘਾਰੀ ਸ੍ਰਣਵਤ ਬੀਜ ਦੀ।","roman":"Khabe dasat ubhaaree gadaa phiraai kai | sainaa sabh sanghaaree sranvat beej dee |","meaning_en":"She raised her left hand, whirling the mace, and destroyed the whole army of Raktabij.","page":246,"meaning_status":"draft"},{"gurmukhi":"ਜਣੁ ਮਦ ਖਾਇ ਮਦਾਰੀ ਘੂਮਨ ਸੂਰਮੇ। ਅਗਣਤ ਪਾਉ ਪਸਾਰੀ ਰੁਲੇ ਅਹਾੜ ਵਿਚਿ।","roman":"Janu mad khaai madaaree ghooman soorme | agnat paau pasaaree rule ahaar vichi |","meaning_en":"The heroes reel like drunkards who have drunk wine. Countless lie sprawled with legs stretched out on the field,","page":246,"meaning_status":"draft","note":"ਮਦਾਰੀ: drinkers / revellers; uncertain. ਅਹਾੜ: battlefield."},{"gurmukhi":"ਜਣੁ ਕਰਿ ਖੇਲਿ ਖਿਲਾਰੀ ਸੁਤੇ ਫਾਗ ਨੋ। ੩੪।","roman":"Janu kari kheli khilaaree sute phaag no | 34 |","meaning_en":"as if Holi players were asleep after their play. (34)","page":246,"meaning_status":"draft","note":"ਫਾਗ: the Holi (Phag) festival."}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":246,"lines":[{"gurmukhi":"ਸ੍ਰਣਵਤ ਬੀਜ ਹਕਾਰੇ ਰਹਿੰਦੇ ਸੂਰਮੇ। ਜੋਧੇ ਵਡੇ ਮੁਨਾਰੇ ਦਿਸਣ ਖੇਤ ਵਿਚ।","roman":"Sranvat beej hakaare rahinde soorme | jodhe vade munaare disan khet vich |","meaning_en":"Raktabij called the heroes who remained. Warriors like great minarets appear on the field.","page":246,"meaning_status":"draft","note":"ਹਕਾਰੇ: called."},{"gurmukhi":"ਸਭਨੀ ਦਸਤ ਉਭਾਰੇ ਤੇਗਾ ਧੂਹਿ ਕੈ। ਮਾਰੋ ਮਾਰੁ ਪੁਕਾਰੇ ਆਏ ਸਾਮ੍ਹਣੇ।","roman":"Sabhnee dasat ubhaare tegaa dhoohi kai | maaro maaru pukaare aae saamhane |","meaning_en":"All raised their hands, drawing their swords. Crying \"Kill! Kill!\" they came forward.","page":246,"meaning_status":"draft"},{"gurmukhi":"ਸੰਜਾ ਤੇ ਠਣਕਾਰੇ ਤੇਗੀ ਉਭਰੇ। ਘਾਟ ਘੜਨਿ ਠਠਿਆਰੇ ਜਾਣਿ ਬਣਾਇ ਕੇ। ੩੫।","roman":"Sanjaa te thankaare tegee ubhre | ghaat gharni thathiaare jaani banaai ke | 35 |","meaning_en":"The swords rang upon the mail with a clang, as if tinsmiths were hammering out vessels. (35)","page":246,"meaning_status":"draft","note":"ਘਾਟ ਘੜਨਿ ਠਠਿਆਰੇ: 'tinsmiths shaping vessels'; uncertain."}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":246,"lines":[{"gurmukhi":"ਸਟ ਪਈ ਜਮਧਾਣੀ ਦਲਾ ਮੁਕਾਬਲਾ। ਘੁਮਰੁ ਬਰਗਸਤਾਣੀ ਰਣ ਵਿਚ ਘਤਿਓ।","roman":"Sat paee jamdhaanee dalaa mukaablaa | ghumru bargastaanee ran vich ghatio |","meaning_en":"The drum of Yama was struck; the armies faced each other. There was a whirl of horse-armour on the field.","page":246,"meaning_status":"draft","note":"ਬਰਗਸਤਾਣੀ: horse-armour (Persian bargustuvan). ਘੁਮਰੁ ... ਘਤਿਓ: read as 'there was confusion / whirling'; uncertain."},{"gurmukhi":"ਸਣੇ ਤੁਰਾ ਪਲਾਣੀ ਡਿਗਣ ਸੂਰਮੇ। ਉਠਿ ਉਠਿ ਮੰਗਨਿ ਪਾਣੀ ਘਾਇਲ ਘੂਮਦੇ।","roman":"Sane turaa palaanee digan soorme | uthi uthi mangni paanee ghaail ghoomde |","meaning_en":"Heroes fall together with their horses and saddles. The wounded, reeling, rise again and again asking for water.","page":246,"meaning_status":"draft"},{"gurmukhi":"ਏਵਡ ਮਾਰੁ ਵਿਹਾਣੀ ਉਤੈ ਰਾਕਸਾ। ਬਿਜਲਿ ਜਿਉ ਝਰਲਾਣੀ ਉਠੀ ਦੇਵਤਾ। ੩੬।","roman":"Evad maaru vihaanee utai raaksaa | bijli jiu jharlaanee uthee devtaa | 36 |","meaning_en":"Such great slaughter came upon the demons; the goddess rose like crashing lightning. (36)","page":246,"meaning_status":"draft","note":"ਝਰਲਾਣੀ: crashing, flashing; uncertain."}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":246,"lines":[{"gurmukhi":"ਚੋਬੀ ਧਉਸ ਉਭਾਰੀ ਦਲਾ ਮੁਕਾਬਲਾ। ਸਭੋ ਸੈਨਾ ਮਰੀ ਪਲ ਵਿਚ ਦਾਨਵੀ ।","roman":"Chobee dhaus ubhaaree dalaa mukaablaa | sabho sainaa maree pal vich daanvee |","meaning_en":"The drummers beat the kettledrum; the armies faced each other. The whole demon army died in a moment.","page":246,"flags":[{"code":"space","reason":"word space printed as a gap (5.7pt), space inserted"}],"meaning_status":"draft"},{"gurmukhi":"ਦੁਰਗਾ ਦਾਨੋ ਮਾਰੇ ਰੋਹ ਬਢਾਇ ਕੈ। ਸਿਰ ਵਿਚ ਤੇਗ ਵਗਾਈ ਸ੍ਰੋਣਵਤਬੀਜ ਦੈ। ੩੭।","roman":"Durgaa daano maare roh badhaai kai | sir vich teg vagaaee sronvatbeej dai | 37 |","meaning_en":"Durga killed the demons with swelling wrath. She struck her sword into the head of Raktabij. (37)","page":246,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"},{"code":"space","reason":"word space printed as a gap (10.3pt), space inserted"}],"meaning_status":"draft","note":"ਸ੍ਰੋਣਵਤਬੀਜ: Raktabij."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":246,"lines":[{"gurmukhi":"ਅਗਣਤ ਦਾਨੋ ਭਾਰੇ ਹੋਏ ਲੋਹੂਆ। ਜੋਧੇ ਜੇਡ ਮੁਨਾਰੇ ਅੰਦਰਿ ਖੇਤ ਦੇ।","roman":"Agnat daano bhaare hoe lohooaa | jodhe jed munaare andri khet de |","meaning_en":"Countless mighty demons arose from the blood, warriors as tall as minarets on the field.","page":246,"meaning_status":"draft","note":"ਹੋਏ ਲੋਹੂਆ: 'came into being from the blood'."},{"gurmukhi":"ਦੁਰਗਾ ਨੋ ਲਲਕਾਰੇ ਆਏ ਸਾਮ੍ਹਣੇ। ਦੁਰਗਾ ਸਭੇ ਸੰਘਾਰੇ ਰਾਕਸ ਆਵਦੇ।","roman":"Durgaa no lalkaare aae saamhane | durgaa sabhe sanghaare raakas aavde |","meaning_en":"Challenging Durga, they came forward; Durga destroyed all the demons as they came.","page":246,"meaning_status":"draft"},{"gurmukhi":"ਰਤੂ ਦੇ ਪਰਨਾਲੇ ਤਿਨ ਤੇ ਭੁਇੰ ਪਏ। ਉਠੇ ਕਾਰਣਿਆਰੇ ਰਾਕਸ ਹੜਹੜਾਇ। ੩੮।","roman":"Ratoo de parnaale tin te bhuin pae | uthe kaarniaare raakas harahraai | 38 |","meaning_en":"Streams of blood fell from them to the earth; from it rose demons, roaring with laughter. (38)","page":246,"meaning_status":"draft","note":"ਕਾਰਣਿਆਰੇ: read as 'mighty / effective ones'; uncertain. ਹੜਹੜਾਇ: loud laughter (sound-word)."}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":246,"lines":[{"gurmukhi":"ਧਗਾ ਸੰਗਲੀਆਲੀ ਸੰਘਰ ਵਾਇਆ। ਬਰਛੀ ਬੁੰਬਲਿਆਲੀ ਸੂਰੇ ਸੰਘਰੇ।","roman":"Dhagaa sangleeaalee sanghar vaaiaa | barchhee bunbliaalee soore sanghre |","meaning_en":"The chained drum was sounded for battle. The heroes in battle with tasselled spears,","page":246,"meaning_status":"draft","note":"ਧਗਾ: drum; uncertain. ਬੁੰਬਲਿਆਲੀ: with tassels."},{"gurmukhi":"ਭੇੜ ਪਇਆ ਬੀਰਾਲੀ ਦੁਰਗਾ ਦਾਨਵੀ। ਮਾਰ ਮਚੀ ਮੁਹਰਾਲੀ ਅੰਦਰਿ ਖੇਤ ਦੇ।","roman":"Bher paiaa beeraalee durgaa daanvee | maar machee muhraalee andri khet de |","meaning_en":"the battle of heroes broke out between Durga and the demons. Slaughter raged in the front of the field,","page":246,"meaning_status":"draft","note":"ਮੁਹਰਾਲੀ: in front, foremost; uncertain."},{"gurmukhi":"ਜਣੁ ਨਟ ਲਥੇ ਛਾਲੀ ਢੋਲ ਵਜਾਇਕੈ। ਲੋਹੂ ਫਾਥੀ ਜਾਲੀ ਲੋਥੀ ਜਮਧੜੀ।","roman":"Janu nat lathe chhaalee dhol vajaaikai | lohoo phaathee jaalee lothee jamadhree |","meaning_en":"as if acrobats were leaping down to the beat of the drum. The daggers, caught in the corpses, were like nets snared with blood.","page":247,"meaning_status":"draft","note":"ਨਟ: acrobats. ਜਮਧੜੀ: daggers. Reading of ਲੋਹੂ ਫਾਥੀ ਜਾਲੀ is uncertain."},{"gurmukhi":"ਘਣ ਵਿਚਿ ਜਿਉ ਚੰਚਾਲੀ ਤੇਗਾ ਹਸੀਆਂ। ਘੁੰਮਰਿਆਰ ਸਿਆਲੀ ਬਣੀਆ ਕੇਜਮਾ। ੩੯।","roman":"Ghan vichi jiu chanchaalee tegaa haseeaan | ghunmriaar siaalee baneeaa kejmaa | 39 |","meaning_en":"The swords flashed like lightning in the clouds; the spears looked like whirling frost.","page":247,"meaning_status":"draft","note":"ਹਸੀਆਂ: 'smiled', i.e. gleamed. ਘੁੰਮਰਿਆਰ ਸਿਆਲੀ: 'dense winter mist' or 'swirling frost'; uncertain. ਕੇਜਮਾ: spears; uncertain."}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":247,"lines":[{"gurmukhi":"ਧਗਾ ਸੂਲ ਬਜਾਈਆ ਦਲਾ ਮੁਕਾਬਲਾ। ਧੂਹਿ ਮਿਆਨੇ ਲਈਆ ਜੁਆਨੀ ਸੂਰਮੀ।","roman":"Dhagaa sool bajaaeeaa dalaa mukaablaa | dhoohi miaane laeeaa juaanee soormee |","meaning_en":"The drums and tridents were sounded; the armies faced each other. The young heroes drew their swords from the scabbards.","page":247,"meaning_status":"draft","note":"ਸੂਲ ਬਜਾਈਆ: read as tridents/spears striking; uncertain."},{"gurmukhi":"ਸ੍ਰੋਣਵਤਬੀਜਿ ਵਧਾਈਆ ਅਗਣਤ ਸੂਰਤਾ। ਦੁਰਗਾ ਸਉਹੈ ਆਈਆ ਰੋਹਿ ਬਢਾਇਕੈ।","roman":"Sronvatbeeji vadhaaeeaa agnat soortaa | durgaa sauhai aaeeaa rohi badhaaikai |","meaning_en":"Raktabij multiplied countless forms of himself. They came before Durga with swelling wrath.","page":247,"meaning_status":"draft","note":"ਸੂਰਤਾ: forms (images) of himself."},{"gurmukhi":"ਸਭਨੀ ਆਨ ਵਗਾਈਆ ਤੇਗਾ ਧੂਹ ਕੈ। ਦੁਰਗਾ ਸਭ ਬਚਾਈਆ ਢਾਲ ਸੰਭਾਲ ਕੈ।","roman":"Sabhnee aan vagaaeeaa tegaa dhooh kai | durgaa sabh bachaaeeaa dhaal sanbhaal kai |","meaning_en":"They all came and struck, drawing their swords; Durga warded them all off, holding up her shield.","page":247,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵੀ ਆਪ ਚਲਾਈਆ ਤਕਿ ਤਕਿ ਦਾਨਵੀ। ਲੋਹੂ ਨਾਲ ਡੁਬਾਈਆ ਤੇਗਾ ਨੰਗੀਆ।","roman":"Devee aap chalaaeeaa taki taki daanvee | lohoo naal dubaaeeaa tegaa nangeeaa |","meaning_en":"Then the goddess herself struck, aiming carefully at the demons. She plunged her bare swords in blood.","page":247,"meaning_status":"draft"},{"gurmukhi":"ਸਾਰਸੁਤੀ ਜਣੁ ਨ੍ਹਾਈਆ ਮਿਲ ਕੈ ਦੇਵੀਆ। ਸਭੇ ਮਾਰਿ ਗਿਰਾਈਆ ਅੰਦਰਿ ਖੇਤ ਦੇ।","roman":"Saarsutee janu nhaaeeaa mil kai deveeaa | sabhe maari giraaeeaa andri khet de |","meaning_en":"It was as if goddesses together had bathed in the Saraswati; she struck them all down on the field.","page":247,"meaning_status":"draft","note":"ਸਾਰਸੁਤੀ: the river Saraswati."},{"gurmukhi":"ਤਿਦੂੰ ਫੇਰਿ ਸਵਾਈਆ ਹੋਈਆ ਸੂਰਤਾ। ੪੦।","roman":"Tidoon pheri savaaeeaa hoeeaa soortaa | 40 |","meaning_en":"Then his forms became a quarter more again. (40)","page":247,"meaning_status":"draft","note":"ਸਵਾਈਆ: one and a quarter times, i.e. increased further."}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":247,"lines":[{"gurmukhi":"ਸੂਰੀ ਸੰਘਰੁ ਰਚਿਆ ਢੋਲ ਸੰਖ ਨਗਾਰੇ ਵਾਇਕੈ।","roman":"Sooree sanghru rachiaa dhol sankh nagaare vaaikai |","meaning_en":"The heroes joined battle, sounding drums, conches and kettledrums.","page":247,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਚਿਤਾਰੀ ਕਾਲਿਕਾ ਮਨਿ ਬਾਹਲਾ ਰੋਹ ਬਢਾਇਕੈ।","roman":"Chandi chitaaree kaalikaa mani baahlaa roh badhaaikai |","meaning_en":"Chandi called Kalika to mind, with great wrath swelling in her heart.","page":247,"meaning_status":"draft","note":"ਚਿਤਾਰੀ: remembered, called to mind."},{"gurmukhi":"ਨਿਕਲੀ ਮਥਾ ਫੋੜਿਕੈ ਜਣੁ ਫਤਹਿ ਨੀਸਾਨ ਬਜਾਇਕੈ।","roman":"Niklee mathaa phorikai janu phathi neesaan bajaaikai |","meaning_en":"Kali came forth bursting out of her forehead, as if sounding the standard of victory.","page":247,"meaning_status":"draft","note":"ਨੀਸਾਨ ਬਜਾਇਕੈ: 'sounding the drum / raising the standard'."},{"gurmukhi":"ਜਾਗਿ ਸੁ ਜੁੰਮੀ ਜੁਧ ਨੋ ਜਰਵਾਣਾ ਜਣੁ ਮਰੜਾਇਕੈ।","roman":"Jaagi su junmee judh no jarvaanaa janu marraaikai |","meaning_en":"Awakened, she set out for battle, like a mighty one crushing all before her.","page":247,"meaning_status":"draft","note":"ਜਰਵਾਣਾ: a powerful one, oppressor. ਮਰੜਾਇਕੈ: crushing, trampling; uncertain."},{"gurmukhi":"ਰਣੁ ਵਿਚਿ ਘੇਰਾ ਘਤਿਆ ਜਣੁ ਸੀਂਹ ਤੁਰਿਆ ਗਣਣਾਇਕੈ।","roman":"Ranu vichi gheraa ghatiaa janu seenh turiaa gannaaikai |","meaning_en":"She set a ring around them on the field, like a lion moving with a roar.","page":247,"meaning_status":"draft","note":"ਗਣਣਾਇਕੈ: roaring; sound-word."},{"gurmukhi":"ਆਪ ਵਿਸੂਲਾ ਹੋਇਆ ਤਿਹੁੰ ਲੋਕਾ ਤੈ ਖੁਣਸਾਇਕੈ।","roman":"Aap visoolaa hoiaa tihun lokaa tai khunsaaikai |","meaning_en":"She herself became furious, raging at the three worlds.","page":247,"meaning_status":"draft","note":"ਵਿਸੂਲਾ: enraged, furious; uncertain. ਖੁਣਸਾਇਕੈ: in fury."},{"gurmukhi":"ਰੋਹ ਸਿਧਾਇਆ ਚਕ੍ਰ ਪਾਣਿ ਕਰਿ ਨੰਦਗ ਖੜਗ ਉਠਾਇਕੈ।","roman":"Roh sidhaaiaa chakr paani kari nandag kharag uthaaikai |","meaning_en":"In wrath she went forth like Vishnu the discus-bearer, raising the sword Nandag.","page":247,"meaning_status":"draft","note":"ਚਕ੍ਰ ਪਾਣਿ: 'discus in hand', a name of Vishnu; ਨੰਦਗ: Nandaka, Vishnu's sword. Could also read 'with discus in hand and raising the sword Nandag'; uncertain."},{"gurmukhi":"ਰਾਕਸ ਬੈਠੇ ਰੋਹਲੇ ਤੀਰ ਤੇਗੀ ਛਹਬਰ ਲਾਇਕੈ।","roman":"Raakas baithe rohle teer tegee chhahbar laaikai |","meaning_en":"The wrathful demons were set, pouring down a shower of arrows and swords.","page":247,"meaning_status":"draft","note":"ਬੈਠੇ: read as 'were engaged / set'; uncertain."},{"gurmukhi":"ਬਹੁਤ ਪਛਾੜੇ ਰਾਕਸਾ ਦਲ ਦੈਤਾ ਅੰਦਰ ਜਾਇਕੈ।","roman":"Bahut pachhaare raaksaa dal daitaa andar jaaikai |","meaning_en":"Going into the army of the demons, she threw down many demons.","page":247,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਕੇਸੀ ਪਕੜਿ ਪਛਾੜਿਅਨਿ ਤਿਨ ਅੰਦਰ ਧੁੰਮ ਰਚਾਇਕੈ।","roman":"Bahu kesee pakri pachhaariani tin andar dhunm rachaaikai |","meaning_en":"Many she seized by the hair and dashed down, raising a commotion among them.","page":247,"meaning_status":"draft"},{"gurmukhi":"ਵਡੇ ਵਡੇ ਚੁਣਿ ਸੂਰਮੇ ਗਹਿ ਕੋਟੀ ਦਏ ਚਲਾਇਕੈ।","roman":"Vade vade chuni soorme gahi kotee dae chalaaikai |","meaning_en":"Picking out the greatest heroes, she seized them by the topknot and hurled them away,","page":247,"meaning_status":"draft","note":"ਕੋਟੀ: read as 'by the topknot / hair' (chotti); uncertain."},{"gurmukhi":"ਰਣਿ ਕਾਲੀ ਗੁਸਾ ਖਾਇਕੈ। ੪੧।","roman":"Rani kaalee gusaa khaaikai | 41 |","meaning_en":"Kali, having grown angry on the field. (41)","page":247,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":247,"lines":[{"gurmukhi":"ਦੁਹਾ ਕੰਧਾਰਾ ਮੁਹ ਜੁੜੇ ਅਣੀਆ ਚੋਈਆ ।","roman":"Duhaa kandhaaraa muh jure aneeaa choeeaa |","meaning_en":"The two armies came face to face; the spear-points dripped.","page":247,"meaning_status":"draft","note":"ਚੋਈਆ: dripped (with blood)."},{"gurmukhi":"ਧੂਹਿ ਕ੍ਰਿਪਾਨਾ ਤ੍ਰਿਖੀਆ ਨਾਲਿ ਲੋਹੂ ਧੋਈਆਂ।","roman":"Dhoohi kripaanaa trikheeaa naali lohoo dhoeeaan |","meaning_en":"Sharp swords were drawn and washed with blood.","page":247,"meaning_status":"draft","note":"ਤ੍ਰਿਖੀਆ: sharp."},{"gurmukhi":"ਹੂਰਾ ਸ੍ਰੋਣਤਬੀਜ ਨੋ ਘਤਿ ਘੇਰ ਖਲੋਈਆ ।","roman":"Hooraa sronatbeej no ghati gher khaloeeaa |","meaning_en":"Heavenly maidens stood surrounding Raktabij,","page":247,"flags":[{"code":"space","reason":"word space printed as a gap (6.1pt), space inserted"}],"meaning_status":"draft","note":"ਹੂਰਾ: houris, heavenly maidens (Persian/Arabic hur). ਸ੍ਰੋਣਤਬੀਜ: Raktabij."},{"gurmukhi":"ਲਾੜਾ ਵੇਖਣਿ ਲਾੜੀਆ ਚਉਗਿਰਦੈ ਹੋਈਆਂ। ੪੨।","roman":"Laaraa vekhni laareeaa chaugirdai hoeeaan | 42 |","meaning_en":"as brides gather all around to see the bridegroom. (42)","page":247,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":247,"lines":[{"gurmukhi":"ਚੌਬੀ ਧਉਸੀ ਪਾਈਆ ਦਲਾ ਭਿੜੰਦਿਆ। ਦਸਤੀ ਧੂਹਿ ਨਚਾਈਆ ਤੇਗਾ ਤਿਖੀਆਂ।","roman":"Chaubee dhausee paaeeaa dalaa bhirandiaa | dastee dhoohi nachaaeeaa tegaa tikheeaan |","meaning_en":"The drummers beat the kettledrums as the armies clashed. Drawing them in their hands, they made the sharp swords dance.","page":247,"meaning_status":"draft","note":"ਚੌਬੀ: drummers."},{"gurmukhi":"ਸੂਰਿਆ ਦੇ ਤਨਿ ਲਾਈਆ ਗੋਸਤ ਗਿਧੀਆਂ। ਵਿਧਣ ਰਾਤੀ ਆਈਆਂ ਮਰਦਾ ਘੋੜਿਆਂ।","roman":"Sooriaa de tani laaeeaa gosat gidheeaan | vidhan raatee aaeeaan mardaa ghoriaan |","meaning_en":"They drove them into the bodies of the heroes, (swords) grown greedy for flesh. A night of hardship came upon men and horses.","page":247,"meaning_status":"draft","note":"ਗੋਸਤ ਗਿਧੀਆਂ: 'used to/greedy for flesh'; uncertain. ਵਿਧਣ ਰਾਤੀ: a night of calamity."},{"gurmukhi":"ਜੋਗਣੀਆ ਮਿਲਿ ਧਾਈਆਂ ਲੋਹੂ ਭਖਣਾ। ਸਭੇ ਮਾਰਿ ਹਟਾਈਆ ਫਉਜਾ ਦਾਨਵਾ।","roman":"Jogneeaa mili dhaaeeaan lohoo bhakhnaa | sabhe maari hataaeeaa phaujaa daanvaa |","meaning_en":"The yoginis rushed together to drink the blood; all the demon armies were killed and driven back.","page":248,"meaning_status":"draft","note":"ਜੋਗਣੀਆ: yoginis, female attendant spirits of the goddess."},{"gurmukhi":"ਭਜਦੀ ਕਥਾ ਸੁਣਾਈਆਂ ਰਾਜੇ ਸੁੰਭ ਨੋ। ਭੁਈ ਨ ਪਉਣੈ ਪਾਈਆਂ ਬੂੰਦਾ ਰਕਤ ਦੀਆ।","roman":"Bhajdee kathaa sunaaeeaan raaje sunbh no | bhuee na paunai paaeeaan boondaa rakat deeaa |","meaning_en":"Those who fled told the tale to King Sumbh: \"Not a drop of the blood was allowed to fall to the ground;","page":248,"meaning_status":"draft","note":"ਭਜਦੀ: printed so; 'the fleeing (ones)'."},{"gurmukhi":"ਕਾਲੀ ਖੇਤ ਖਪਾਈਆਂ ਸਭੈ ਸੂਰਤਾ। ਬਹੁਤੀ ਸਿਰੀ ਵਿਹਾਈਆ ਘੜੀਆ ਕਾਲ ਦੀਆ।","roman":"Kaalee khet khapaaeeaan sabhai soortaa | bahutee siree vihaaeeaa ghareeaa kaal deeaa |","meaning_en":"Kali destroyed all the forms on the field.\" Many heads were visited by the hours of death.","page":248,"meaning_status":"draft","note":"ਸਿਰੀ ਵਿਹਾਈਆ ਘੜੀਆ ਕਾਲ ਦੀਆ: 'the hours of death passed over (their) heads'; read as 'many met their death'."},{"gurmukhi":"ਜਾਣੁ ਨ ਜਾਏ ਮਾਈਆ ਜੂਝੇ ਸੂਰਮੇ। ੪੩।","roman":"Jaanu na jaae maaeeaa joojhe soorme | 43 |","meaning_en":"The heroes who fell were as if their mothers had never borne them. (43)","page":248,"meaning_status":"draft","note":"ਜਾਣੁ ਨ ਜਾਏ ਮਾਈਆ: 'as if not born of mothers', i.e. wiped out without trace; uncertain."}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":248,"lines":[{"gurmukhi":"ਸੁੰਭ ਸੁਣੀ ਕਰਹਾਲੀ ਸ੍ਰੋਣਤ ਬੀਜ ਦੀ। ਰਣ ਵਿਚਿ ਕਿਨੈ ਨ ਝਾਲੀ ਦੁਰਗਾ ਆਵਦੀ।","roman":"Sunbh sunee karhaalee sronat beej dee | ran vichi kinai na jhaalee durgaa aavdee |","meaning_en":"Sumbh heard of the death of Raktabij: no one on the field could withstand Durga as she came.","page":248,"meaning_status":"draft","note":"ਕਰਹਾਲੀ: news of the death / calamity; uncertain. ਝਾਲੀ: withstood."},{"gurmukhi":"ਬਹੁਤੇ ਬੀਰ ਜਟਲੀ ਉਠੇ ਆਖਿ ਕੈ। ਚੋਟਾਂ ਪਾਨ ਤਬਾਲੀ ਜਾਸਨ ਜੁਧ ਨੋ।","roman":"Bahute beer jatlee uthe aakhi kai | chotaan paan tabaalee jaasan judh no |","meaning_en":"Many matted-haired warriors rose up, saying, \"We will go to war\"; drums were struck for them to go to battle.","page":248,"meaning_status":"draft","note":"ਚੋਟਾਂ ਪਾਨ ਤਬਾਲੀ: 'the drummers strike blows'; uncertain. ਜਾਸਨ: will go."},{"gurmukhi":"ਥਰ ਥਰ ਪਿਰਥੀ ਹਾਲੀ ਦਲਾ ਚੜੰਦਿਆਂ। ਨਾਉ ਜਿਵੈ ਹੈ ਹਾਲੀ ਸਹ ਦਰਿਆਉ ਵਿਚਿ।","roman":"Thar thar pirthee haalee dalaa charandiaan | naau jivai hai haalee sah dariaau vichi |","meaning_en":"As the armies marched, the earth shook and trembled, as a boat rocks in a flowing river.","page":248,"meaning_status":"draft","note":"ਥਰ ਥਰ: trembling (sound-word)."},{"gurmukhi":"ਧੂੜਿ ਉਤਾਹਾ ਘਾਲੀ ਖੁਰੀ ਤਰੰਗਮਾਂ। ਜਾਣ ਪੁਾਕਰੂ ਚਾਲੀ ਧਰਤੀ ਇੰਦ੍ਰ ਥੈ। ੪੪।","roman":"Dhoori utaahaa ghaalee khuree tarangmaan | jaan paakroo chaalee dhartee indr thai | 44 |","meaning_en":"The horses' hooves raised the dust high, as if the earth were going to Indra to complain. (44)","page":248,"meaning_status":"draft","note":"ਪੁਾਕਰੂ: printed so; read as ਪੁਕਾਰੂ, a complainant."}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":248,"lines":[{"gurmukhi":"ਆਹਰੁ ਮਿਲਿਆ ਆਹਰੀਆ ਸੈਨ ਸੂਰਿਆ ਸਾਜੀ।","roman":"Aahru miliaa aahreeaa sain sooriaa saajee |","meaning_en":"The workers found their work: the heroes arrayed their army.","page":248,"meaning_status":"draft","note":"ਆਹਰੁ ਮਿਲਿਆ ਆਹਰੀਆ: 'the task met those whose task it is', i.e. warriors found their war; uncertain."},{"gurmukhi":"ਚਲੇ ਸਉਹੈ ਦੁਰਗਸਾਹ ਜਣੁ ਕਾਬੇ ਹਾਜੀ।","roman":"Chale sauhai duragsaah janu kaabe haajee |","meaning_en":"They went before Durga, the sovereign, like pilgrims to the Kaaba.","page":248,"meaning_status":"draft","note":"ਕਾਬੇ ਹਾਜੀ: hajis (pilgrims) to the Kaaba."},{"gurmukhi":"ਤੀਰੀ ਤੇਗੀ ਜਮਧੜੀ ਰਣਿ ਵੰਡੀ ਭਾਜੀ।","roman":"Teeree tegee jamadhree rani vandee bhaajee |","meaning_en":"On the field she dealt out arrows, swords and daggers like portions of food.","page":248,"meaning_status":"draft","note":"ਵੰਡੀ ਭਾਜੀ: 'distributed bhaji' (sweetmeats/portions sent as gifts); i.e. dealt out blows to all."},{"gurmukhi":"ਇਕ ਘੁਮਨਿ ਘਾਇਲ ਸੂਰਮੇ ਜਣੁ ਮਕਤਬਿ ਕਾਜੀ।","roman":"Ik ghumni ghaail soorme janu makatbi kaajee |","meaning_en":"Some wounded heroes sway like qazis in a school,","page":248,"meaning_status":"draft","note":"ਮਕਤਬਿ: school (Arabic maktab); ਕਾਜੀ: qazi, Muslim judge/teacher (swaying as they recite)."},{"gurmukhi":"ਇਕ ਬੀਰ ਪਰੋਤੇ ਬਰਛੀਐ ਜਿਉ ਝੁਕਿ ਪਉਨ ਨਵਾਜੀ।","roman":"Ik beer parote barchheeai jiu jhuki paun navaajee |","meaning_en":"some warriors are pierced on spears, bowed like one bending in prayer.","page":248,"meaning_status":"draft","note":"ਨਵਾਜੀ: one offering namaz (prayer); ਪਉਨ: read as 'bending/falling'; uncertain."},{"gurmukhi":"ਇਕ ਦੇਵੀ ਸਉਹੈ ਖੁਣਸ ਕੇ ਖੁਣਸਾਇਨ ਤਾਜੀ।","roman":"Ik devee sauhai khunas ke khunsaain taajee |","meaning_en":"Some, enraged, spur their swift horses in fury against the goddess,","page":248,"meaning_status":"draft","note":"ਤਾਜੀ: Arab (Tazi) horses. ਖੁਣਸਾਇਨ: urge on in fury; uncertain."},{"gurmukhi":"ਇਕ ਧਾਵਨਿ ਜਾਪਨਿ ਸਾਮ੍ਹਣੇ ਜਿਉ ਭੁਖਿਆਏ ਪਾਜੀ।","roman":"Ik dhaavni jaapni saamhane jiu bhukhiaae paajee |","meaning_en":"some rush forward like starving rogues.","page":248,"meaning_status":"draft","note":"ਪਾਜੀ: base fellows, rogues; uncertain."},{"gurmukhi":"ਕਦੇ ਨ ਰਜੇ ਜੁਧ ਤੇ ਰਜਿ ਹੋਏ ਰਾਜੀ। ੪੫।","roman":"Kade na raje judh te raji hoe raajee | 45 |","meaning_en":"Never sated with war, they are now satisfied and content. (45)","page":248,"meaning_status":"draft","note":"ਰਜਿ ਹੋਏ ਰਾਜੀ: 'having had their fill, became content' (i.e. in death); uncertain."}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":248,"lines":[{"gurmukhi":"ਬਜੇ ਸੰਗਲੀਆਲੇ ਸੰਘਰਿ ਡੋਹਰੇ। ਖੇਤ ਡਹੇ ਜਟਾਲੇ ਹਾਠਾ ਜੋੜਿਕੈ।","roman":"Baje sangleeaale sanghri dohre | khet dahe jataale haathaa jorikai |","meaning_en":"The double, chained drums sounded in the battle. The matted-haired warriors joined battle, locking their thighs (stubbornly).","page":248,"meaning_status":"draft","note":"ਹਾਠਾ ਜੋੜਿਕੈ: 'joining ranks / closing in'; uncertain."},{"gurmukhi":"ਨੇਜੇ ਬੰਬਲਿਆਲੇ ਦਿਸਿਨਿ ਓਰੜੈ। ਚਲੇ ਜਾਣ ਜਟਾਲੇ ਨ੍ਹਾਵਣੇ ਗੰਗ ਦੇ। ੪੬।","roman":"Neje banbliaale disini orrai | chale jaan jataale nhaavne gang de | 46 |","meaning_en":"The tasselled lances appear as they press forward, as if the matted-haired ones were going to bathe in the Ganga. (46)","page":248,"meaning_status":"draft","note":"ਓਰੜੈ: pressing forward, rushing."}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":248,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਅਤੇ ਦਾਨਵੀ ਸੂਲ ਹੋਈਆਂ ਕੰਗਾਂ।","roman":"Durgaa ate daanvee sool hoeeaan kangaan |","meaning_en":"Between Durga and the demons the spears clashed like shoots of grain.","page":248,"meaning_status":"draft","note":"ਸੂਲ: spears/tridents. ਕੰਗਾਂ: read as standing grain stalks or a clash; uncertain."},{"gurmukhi":"ਵਾਛੜ ਘਤੀ ਸੂਰਿਆਂ ਵਿਚ ਖੇਤ ਖਤੰਗਾਂ।","roman":"Vaachhar ghatee sooriaan vich khet khatangaan |","meaning_en":"The heroes poured a shower of arrows on the field.","page":248,"meaning_status":"draft","note":"ਖਤੰਗਾਂ: arrows (Persian khadang)."},{"gurmukhi":"ਧੂਹਿ ਕ੍ਰਿਪਾਣਾਂ ਤਿਖੀਆਂ ਬਢਿ ਲਾਹਨਿ ਅੰਗਾਂ।","roman":"Dhoohi kripaanaan tikheeaan badhi laahni angaan |","meaning_en":"Drawing sharp swords, they hack off limbs.","page":248,"meaning_status":"draft"},{"gurmukhi":"ਪਹਿਲਾ ਦਲਾ ਮਿਲੰਦਿਆਂ ਭੇੜੁ ਪਾਇਆ ਨਿਹੰਗਾਂ।੪੭।","roman":"Pahilaa dalaa milandiaan bheru paaiaa nihangaan | 47 |","meaning_en":"As the armies first met, the warriors joined battle. (47)","page":248,"meaning_status":"draft","note":"ਨਿਹੰਗਾਂ: fearless warriors."}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":248,"lines":[{"gurmukhi":"ਓਰੜਿ ਫਉਜਾ ਆਈਆਂ ਬੀਰ ਚੜੇ ਕੰਧਾਰੀ। ਸੜਕਿ ਮਿਆਨਹੁਂ ਕਢੀਆ ਤਿਖੀਆ ਤਰਵਾਰੀ।","roman":"Orri phaujaa aaeeaan beer chare kandhaaree | sarki miaanhun kadheeaa tikheeaa tarvaaree |","meaning_en":"The armies came pressing forward; the heroes mounted their battle-lines. With a swish they drew sharp swords from the scabbards.","page":248,"meaning_status":"draft","note":"ਕੰਧਾਰੀ: battle-lines; uncertain. ਸੜਕਿ: with a swishing sound."},{"gurmukhi":"ਕੜਕਿ ਉਠੇ ਰਣ ਮਚਿਆ ਵਡੇ ਹੰਕਾਰੀ। ਸਿਰ ਧੜ ਬਾਹਾ ਗਨਲੇ ਫੁਲ ਜੇਹੇ ਬਾੜੀ।","roman":"Karki uthe ran machiaa vade hankaaree | sir dhar baahaa ganle phul jehe baaree |","meaning_en":"The great proud ones rose with a roar and battle raged; heads, trunks and arms lay like flowers in a garden.","page":248,"meaning_status":"draft","note":"ਗਨਲੇ: read as 'heaped / scattered'; uncertain. ਬਾੜੀ: garden."},{"gurmukhi":"ਜਣੁਕਰਿ ਕਟੇ ਬਾਢੀਆਂ ਰੁਖ ਚੰਦਨਿ ਆਰੀ। ੪੮।","roman":"Janukri kate baadheeaan rukh chandni aaree | 48 |","meaning_en":"as if carpenters had cut sandalwood trees with a saw. (48)","page":248,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":249,"lines":[{"gurmukhi":"ਦੁਹਾਂ ਕੰਧਾਰਾ ਮੁਹਿ ਜੁੜੇ ਰਣਿ ਸਟ ਪਈ ਖਰਵਾਰ ਕਉ।","roman":"Duhaan kandhaaraa muhi jure rani sat paee kharvaar kau |","meaning_en":"The two armies came face to face; on the field the drum of ass-hide was struck.","page":249,"meaning_status":"draft","note":"ਖਰਵਾਰ: read as the drum (of ass-hide), cf. ਖਰਚਾਮੀ; uncertain."},{"gurmukhi":"ਤਕ ਤਕ ਕੈਬਰ ਦੁਰਗਸਾਹ ਤਕਿ ਮਾਰੈ ਭਲੇ ਜੁਝਾਰ ਕਉ।","roman":"Tak tak kaibar duragsaah taki maarai bhale jujhaar kau |","meaning_en":"Durga, the sovereign, aiming her arrows again and again, aimed and struck the good warriors.","page":249,"meaning_status":"draft"},{"gurmukhi":"ਪੈਦਲ ਮਾਰੇ ਹਾਥੀਆ ਸੰਗਿ ਰਥ ਗਿਰੇ ਅਸਵਾਰ ਕਉ।","roman":"Paidal maare haatheeaa sangi rath gire asvaar kau |","meaning_en":"She killed foot-soldiers and elephants; with them, chariots fell along with their riders.","page":249,"meaning_status":"draft"},{"gurmukhi":"ਸੋਹਨਿ ਸੰਜਾ ਬਾਗੜਾ ਜਣੁ ਲਗੇ ਫੁਲ ਅਨਾਰ ਕਉ।","roman":"Sohni sanjaa baagraa janu lage phul anaar kau |","meaning_en":"Their coats of mail shone like the flowers on a pomegranate.","page":249,"meaning_status":"draft","note":"ਬਾਗੜਾ: read as 'shone (red)'; uncertain."},{"gurmukhi":"ਗੁਸੇ ਆਈ ਕਾਲਿਕਾ ਹਥ ਸਜੇ ਲੈ ਤਰਵਾਰ ਕਉ।","roman":"Guse aaee kaalikaa hath saje lai tarvaar kau |","meaning_en":"In anger came Kalika, taking the sword in her right hand.","page":249,"meaning_status":"draft"},{"gurmukhi":"ਏਦੂੰ ਪਾਰੋ ਓਤ ਪਾਰ ਹਰਿਨਾਕਸਿ ਕਈ ਹਜ਼ਾਰ ਕਉ।","roman":"Edoon paaro ot paar harinaaksi kaee hazaar kau |","meaning_en":"From this end to that end she destroyed many thousands of Harnakhashes,","page":249,"meaning_status":"draft","note":"ਹਰਿਨਾਕਸਿ: Harnakash (Hiranyakashipu), here as a type of mighty demon."},{"gurmukhi":"ਜਿਣਿ ਇਕੋ ਰਹੀ ਕੰਧਾਰ ਕਉ। ਸਦ ਰਹਮਤਿ ਤੇਰੇ ਵਾਰ ਕਉ।੪੯।","roman":"Jini iko rahee kandhaar kau | sad rahamti tere vaar kau | 49 |","meaning_en":"she alone conquered the (enemy) army. Ever be praise to your blows! (49)","page":249,"meaning_status":"draft","note":"ਰਹਮਤਿ: 'blessing, praise' (Arabic rahmat); here as acclaim. ਵਾਰ: blow, attack."}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":249,"lines":[{"gurmukhi":"ਦੁਹਾ ਕੰਧਾਰਾ ਮੁਹਿ ਜੁੜੇ ਸਟ ਪਈ ਜਮਧਾਣ ਕਉ।","roman":"Duhaa kandhaaraa muhi jure sat paee jamdhaan kau |","meaning_en":"The two armies came face to face; the drum of Yama was struck.","page":249,"meaning_status":"draft","note":"ਜਮਧਾਣ: drum of death/Yama; uncertain."},{"gurmukhi":"ਤਦਿ ਖਿੰਗ ਨਿਸੁੰਭ ਨਚਾਇਆ ਡਾਲਿ ਉਪਰ ਬਰਗੁਸਤਾਣ ਕਉ।","roman":"Tadi khing nisunbh nachaaiaa daali upar bargustaan kau |","meaning_en":"Then Nisumbh made his white horse dance, its horse-armour put on over it,","page":249,"meaning_status":"draft","note":"ਖਿੰਗ: a white horse. ਡਾਲਿ: 'putting on'. ਬਰਗੁਸਤਾਣ: horse-armour."},{"gurmukhi":"ਫੜੀ ਬਿਲੰਦ ਮੰਗਾਇਓਸੁ ਫਰਮਾਇਸ ਕਰਿ ਮੁਲਤਾਨ ਕਉ।","roman":"Pharee biland mangaaiosu pharmaais kari multaan kau |","meaning_en":"a lofty one which he had sent for, having ordered it from Multan.","page":249,"meaning_status":"draft","note":"ਫੜੀ ਬਿਲੰਦ: read as 'a lofty (horse)' or 'a tall (saddle/armour)'; uncertain."},{"gurmukhi":"ਗੁਸੇ ਆਈ ਸਾਮ੍ਹਣੇ ਰਣ ਅੰਦਰ ਘਤਣ ਘਾਣ ਕਉ।","roman":"Guse aaee saamhane ran andar ghatan ghaan kau |","meaning_en":"The goddess came before him in anger to make a slaughter on the field.","page":249,"meaning_status":"draft","note":"ਘਤਣ ਘਾਣ: to make a slaughter (a press-load)."},{"gurmukhi":"ਅਗੇ ਤੇਗ ਵਗਾਈ ਦੁਰਗਸਾਹ ਬਢਿ ਸੁੰਭਨ ਬਹੀ ਪਲਾਣ ਕਉ।","roman":"Age teg vagaaee duragsaah badhi sunbhan bahee palaan kau |","meaning_en":"Durga, the sovereign, struck with her sword first, cutting through Nisumbh where he sat on the saddle.","page":249,"meaning_status":"draft","note":"ਸੁੰਭਨ: printed so; read as Nisumbh (named in 1.54.1, 1.54.6 says ਸੁੰਭ); uncertain whether Sumbh or Nisumbh is meant. ਪਲਾਣ: saddle."},{"gurmukhi":"ਰੜਕੀ ਜਾਇ ਕੈ ਧਰਤ ਕਉ ਬਢਿ ਪਾਖਰ ਬਢਿ ਕਿਕਾਣ ਕਉ।","roman":"Rarkee jaai kai dharat kau badhi paakhar badhi kikaan kau |","meaning_en":"Cutting the horse-armour and cutting the horse, it went and struck the earth.","page":249,"meaning_status":"draft","note":"ਕਿਕਾਣ: horse."},{"gurmukhi":"ਬੀਰ ਪਲਾਣੋ ਡਿਗਿਆ ਕਰਿ ਸਿਜਦਾ ਸੁੰਭ ਸੁਜਾਣ ਕਉ।","roman":"Beer palaano digiaa kari sijdaa sunbh sujaan kau |","meaning_en":"The hero fell from the saddle, bowing in salutation to the wise Sumbh.","page":249,"meaning_status":"draft","note":"ਸਿਜਦਾ: prostration (Arabic sajda). ਸੁੰਭ ਸੁਜਾਣ: 'wise Sumbh' (his elder brother/king); uncertain."},{"gurmukhi":"ਸਾਬਾਸ ਸਲੋਣੇ ਖਾਨ ਕਉ। ਸਦ ਸਾਬਾਸ ਤੇਰੇ ਤਾਣ ਕਉ।","roman":"Saabaas salone khaan kau | sad saabaas tere taan kau |","meaning_en":"Bravo to the handsome chief! Ever bravo to your strength!","page":249,"meaning_status":"draft","note":"ਸਲੋਣੇ ਖਾਨ: 'the comely khan' (chief); likely Nisumbh, praised for his valour."},{"gurmukhi":"ਤਾਰੀਫਾ ਪਾਨ ਚਬਾਣ ਕਉ। ਸਦ ਰਹਮਤ ਕੈਫਾ ਖਾਣ ਕਉ।","roman":"Taareephaa paan chabaan kau | sad rahmat kaiphaa khaan kau |","meaning_en":"Praise for your chewing of betel; ever blessed your drinking of wine;","page":249,"meaning_status":"draft","note":"ਕੈਫਾ: intoxicants (Arabic kaif)."},{"gurmukhi":"ਸਦ ਰਹਮਤ ਤੁਰੇ ਨਚਾਣ ਕਉ।੫੦।","roman":"Sad rahmat ture nachaan kau | 50 |","meaning_en":"ever blessed your making of horses dance. (50)","page":249,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":249,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਅਤੇ ਦਾਨਵੀ ਗਹਿ ਸੰਘਰ ਕਥੇ।","roman":"Durgaa ate daanvee gahi sanghar kathe |","meaning_en":"Durga and the demons took up battle,","page":249,"meaning_status":"draft","note":"ਕਥੇ: read as 'set about / engaged'; uncertain."},{"gurmukhi":"ਓਰੜ ਉਠੇ ਸੂਰਮੇ ਆਇ ਡਾਹੈ ਮਥੇ।","roman":"Orar uthe soorme aai daahai mathe |","meaning_en":"the heroes rose and pressed forward, coming to face one another.","page":249,"meaning_status":"draft","note":"ਆਇ ਡਾਹੈ ਮਥੇ: came and set foreheads (faced each other)."},{"gurmukhi":"ਕਟਿ ਤੁੰਫੰਗੀ ਕੈਬਰੀ ਦਲ ਸਾਹਿਬ ਨਿਕਥੇ।","roman":"Kati tunphangee kaibree dal saahib nikthe |","meaning_en":"Guns and arrows were cut through, and the army commanders came forth.","page":249,"meaning_status":"draft","note":"ਤੁੰਫੰਗੀ: muskets (Persian tufang). ਨਿਕਥੇ: read as 'came out'; or 'the commanders of the armies were cut down'; uncertain."},{"gurmukhi":"ਵੇਖਣਿ ਜੰਗ ਫਰੇਸਤੇ ਅਸਮਾਨਹੁੰ ਲਥੇ। ੫੧।","roman":"Vekhni jang phareste asmaanhun lathe | 51 |","meaning_en":"Angels came down from the sky to see the battle. (51)","page":249,"meaning_status":"draft","note":"ਫਰੇਸਤੇ: angels (Persian firishta)."}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":249,"lines":[{"gurmukhi":"ਦੋਹਾਂ ਕੰਧਾਰਾ ਮੁਹ ਜੁੜੇ ਦਲ ਘੁਰੇ ਨਗਾਰੇ। ਓਰੜਿ ਆਏ ਸੂਰਮੇ ਸਿਰਦਾਰ ਰਣਿਆਰੇ ।","roman":"Dohaan kandhaaraa muh jure dal ghure nagaare | orri aae soorme sirdaar raniaare |","meaning_en":"The two armies came face to face; the drums thundered in the armies. The heroes, chiefs eager for battle, pressed forward.","page":249,"flags":[{"code":"space","reason":"word space printed as a gap (6.0pt), space inserted"}],"meaning_status":"draft","note":"ਰਣਿਆਰੇ: warlike, fond of battle."},{"gurmukhi":"ਲੈ ਲੈ ਤੇਗਾ ਬਰਛੀਆ ਹਥਿਆਰ ਉਭਾਰੇ। ਟੋਪ ਪਟੇਲਾ ਪਾਖਰਾ ਗਲਿ ਸੰਜ ਸਵਾਰੇ।","roman":"Lai lai tegaa barchheeaa hathiaar ubhaare | top patelaa paakhraa gali sanj savaare |","meaning_en":"Taking swords and spears, they raised their weapons; helmets, belts, horse-armour, and mail fitted round their necks.","page":249,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕੇ ਬਰਛੀ ਦੁਰਗਸਾਹ ਬਹੁ ਦਾਨਵ ਮਾਰੇ। ਚੜੇ ਰਥੀ ਗਜ ਘੋੜਿਈ ਮਾਰਿ ਭੁਇ ਤੇ ਡਾਰੇ।","roman":"Lai ke barchhee duragsaah bahu daanav maare | chare rathee gaj ghoriee maari bhui te daare |","meaning_en":"Taking her spear, Durga the sovereign killed many demons; those riding chariots, elephants and horses she struck down to the ground,","page":249,"meaning_status":"draft"},{"gurmukhi":"ਜਣੁ ਹਲਵਾਈ ਸੀਖ ਨਾਲ ਬਿੰਨ੍ਹ ਵੜੇ ਉਤਾਰੇ। ੫੨।","roman":"Janu halvaaee seekh naal binnh vare utaare | 52 |","meaning_en":"as a confectioner takes off fritters, pierced on a skewer. (52)","page":249,"meaning_status":"draft","note":"ਵੜੇ: fritters (vada)."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":250,"lines":[{"gurmukhi":"ਦੁਹਾ ਕੰਧਾਰਾ ਮੁਹਿ ਜੁੜੇ ਨਾਲ ਧਉਸਾ ਭਾਰੀ।","roman":"Duhaa kandhaaraa muhi jure naal dhausaa bhaaree |","meaning_en":"The two armies came face to face with the heavy kettledrums.","page":250,"meaning_status":"draft"},{"gurmukhi":"ਲਈ ਭਗਉਤੀ ਦੁਰਗਸਾਹਿ ਵਰ ਜਾਗਣਿ ਭਾਰੀ।","roman":"Laee bhagautee duragsaahi var jaagni bhaaree |","meaning_en":"Durga, the sovereign, took the sword Bhagauti, gleaming greatly like a great flame.","page":250,"meaning_status":"draft","note":"ਭਗਉਤੀ: here the sword. ਵਰ ਜਾਗਣਿ ਭਾਰੀ: read as 'blazing like a great fire'; uncertain."},{"gurmukhi":"ਲਾਈ ਰਾਜੇ ਸੁੰਭ ਨੋ ਰਤ ਪੀਐ ਪਿਆਰੀ।","roman":"Laaee raaje sunbh no rat peeai piaaree |","meaning_en":"She struck it into King Sumbh; the beloved (sword) drank blood.","page":250,"meaning_status":"draft"},{"gurmukhi":"ਸੁੰਭ ਪਾਲਾਣੋ ਡਿਗਿਆ ਉਪਮਾ ਵੀਚਾਰੀ।","roman":"Sunbh paalaano digiaa upmaa veechaaree |","meaning_en":"Sumbh fell from the saddle; I have thought of this simile:","page":250,"meaning_status":"draft","note":"ਪਾਲਾਣੋ: from the saddle."},{"gurmukhi":"ਡੁਬਿ ਰਤੁ ਨਾਲਹੁ ਨਿਕਲੀ ਬਰਛੀ ਦੋ ਧਾਰੀ।","roman":"Dubi ratu naalhu niklee barchhee do dhaaree |","meaning_en":"the double-edged sword, dipped in blood, came out of him,","page":250,"meaning_status":"draft","note":"ਬਰਛੀ: here the blade; ਨਾਲਹੁ: from (him)."},{"gurmukhi":"ਜਾਣੁ ਰਜਾਦੀ ਉਤੀ ਪੈਨ੍ਹਿ ਸੂਹੀ ਸਾਰ੍ਹੀ। ੫੩।","roman":"Jaanu rajaadee utee painhi soohee saarhee | 53 |","meaning_en":"like a princess descending, dressed in a red sari. (53)","page":250,"meaning_status":"draft","note":"ਰਜਾਦੀ: princess (rajaadi); uncertain. ਸੂਹੀ ਸਾਰ੍ਹੀ: red sari."}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":250,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਅਤੇ ਦਾਨਵੀ ਭੇੜ ਪਇਆ ਸਬਾਹੀਂ।","roman":"Durgaa ate daanvee bher paiaa sabaaheen |","meaning_en":"The battle between Durga and the demons began in the morning.","page":250,"meaning_status":"draft","note":"ਸਬਾਹੀਂ: in the morning (Arabic sabaah)."},{"gurmukhi":"ਸਸਤ੍ਰ ਪਜੂਤੇ ਦੁਰਗਸਾਹ ਗਹਿ ਸਭਨੀ ਬਾਹੀਂ।","roman":"Sasatr pajoote duragsaah gahi sabhnee baaheen |","meaning_en":"Durga, the sovereign, gripped her weapons firmly in all her arms.","page":250,"meaning_status":"draft","note":"ਪਜੂਤੇ: read as 'took firmly / wielded'; uncertain."},{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਸੰਘਾਰਿਆ ਵਥ ਜੇ ਹੈ ਸਾਹੀਂ।","roman":"Sunbh nisunbh sanghaariaa vath je hai saaheen |","meaning_en":"She destroyed Sumbh and Nisumbh, who were the great kings.","page":250,"meaning_status":"draft","note":"ਵਥ ਜੇ ਹੈ ਸਾਹੀਂ: 'who were the essence of kingship / masters of wealth'; uncertain."},{"gurmukhi":"ਫਉਜਾ ਰਾਕਸ ਆਰੀਆਂ ਵੇਖ ਰੋਵਨਿ ਧਾਹੀਂ।","roman":"Phaujaa raakas aareeaan vekh rovni dhaaheen |","meaning_en":"The demon armies, helpless, seeing this, wail loudly.","page":250,"meaning_status":"draft","note":"ਆਰੀਆਂ: helpless (aaree); uncertain."},{"gurmukhi":"ਮੁਹਿ ਕੜੂਚੇ ਘਾਹੁ ਦੇ ਛਡਿ ਘੋੜੇ ਰਾਹੀਂ।","roman":"Muhi karooche ghaahu de chhadi ghore raaheen |","meaning_en":"Putting straw in their mouths (in surrender), they abandon their horses on the roads.","page":250,"meaning_status":"draft","note":"ਮੁਹਿ ਕੜੂਚੇ ਘਾਹੁ ਦੇ: grass in the teeth, a sign of submission; uncertain wording."},{"gurmukhi":"ਭਜਦੇ ਹੋਇ ਮਾਰੀਅਨ ਮੁੜਿ ਝਾਕਨਿ ਨਾਹੀਂ। ੫੪।","roman":"Bhajde hoi maareean muri jhaakni naaheen | 54 |","meaning_en":"Fleeing, they are killed; they do not look back. (54)","page":250,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":250,"lines":[{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਪਠਾਇਆ ਜਮ ਦੇ ਧਾਮ ਨੋ।","roman":"Sunbh nisunbh pathaaiaa jam de dhaam no |","meaning_en":"She sent Sumbh and Nisumbh to the abode of Yama.","page":250,"meaning_status":"draft"},{"gurmukhi":"ਇੰਦ੍ਰ ਸਦਿ ਬੁਲਾਇਆ ਰਾਜ ਅਭਿਖੇਖ ਨੋ।","roman":"Indr sadi bulaaiaa raaj abhikhekh no |","meaning_en":"She summoned Indra for his coronation.","page":250,"meaning_status":"draft","note":"ਅਭਿਖੇਖ: abhishek, anointing/coronation."},{"gurmukhi":"ਸਿਰ ਪਰ ਛਤ੍ਰ ਫਿਰਾਇਆ ਰਾਜੇ ਇੰਦ੍ਰ ਦੇ।","roman":"Sir par chhatr phiraaiaa raaje indr de |","meaning_en":"She had the canopy waved over the head of King Indra.","page":250,"meaning_status":"draft"},{"gurmukhi":"ਚਉਦੀ ਲੋਕੀ ਛਾਇਆ ਜਸੁ ਜਗਮਾਤ ਦਾ।","roman":"Chaudee lokee chhaaiaa jasu jagmaat daa |","meaning_en":"The glory of the Mother of the World spread over the fourteen worlds.","page":250,"meaning_status":"draft"},{"gurmukhi":"ਦੁਰਗਾ ਪਾਠ ਬਣਾਇਆ ਸਭੇ ਪਉੜੀਆ।","roman":"Durgaa paath banaaiaa sabhe paureeaa |","meaning_en":"All these pauris have been made as the recitation of Durga;","page":250,"meaning_status":"draft","note":"ਦੁਰਗਾ ਪਾਠ: the recitation of Durga (Durga Path)."},{"gurmukhi":"ਫੇਰਿ ਨ ਜੂਨੀ ਆਇਆ ਜਿਨਿ ਇਹ ਗਾਇਆ। ੫੫।","roman":"Pheri na joonee aaiaa jini ih gaaiaa | 55 |","meaning_en":"whoever sings this will not come into births again. (55)","page":250,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦੁਰਗਾ ਕੀ ਵਾਰ ਸਮਾਪਤੰ ਸਤੁ ਸੁਭਮ ਸਤੁ।","roman":"Iti sree durgaa kee vaar samaaptan satu subham satu |","meaning_en":"Here ends the Var of Sri Durga. All is true and auspicious.","page":250,"meaning_status":"draft","note":"ਸਤੁ ਸੁਭਮ ਸਤੁ: 'true, auspicious, true'."}],"page":250}});
